// @refresh reset
// 订单创建页使用动态 Form.List；开发时更新本模块后应重新挂载，不能复用旧的 Hook 状态。
import { useCallback, useEffect, useRef, useState } from 'react';
import { AppstoreOutlined, BarChartOutlined, DeleteOutlined, FileTextOutlined, HomeOutlined, LogoutOutlined, MenuFoldOutlined, MenuUnfoldOutlined, PlusOutlined, TeamOutlined, TruckOutlined, WalletOutlined } from '@ant-design/icons';
import { Alert, AutoComplete, Avatar, Button, Card, Checkbox, Col, Descriptions, Divider, Drawer, Dropdown, Form, Input, InputNumber, Layout, Menu, Modal, Row, Select, Space, Spin, Statistic, Table, Tag, Typography, Upload, message } from 'antd';
import type { MenuProps } from 'antd';
import * as XLSX from 'xlsx';

const { Header, Sider, Content } = Layout;
const API = import.meta.env.VITE_API_BASE ?? '/api';
type Tab = { key: string; label: string };
type Context = { data: any; request: (path: string, options?: RequestInit) => Promise<Response>; refresh: () => Promise<void>; logout: () => void; };

const labels: Record<string, string> = {
  home: '首页', 'order-list': '订单列表', 'order-create': '创建运单', 'order-import': 'Excel 导入',
  'customer-list': '客户', 'balance-alerts': '余额预警设置', 'supplier-channels': '供应商与渠道', 'service-management': '服务管理',
  'cost-tables': '供应商成本表', 'profit-tables': '服务利润表', 'remote-templates': '偏远地址模板',
  reconciliation: '订单对账', 'supplier-bills': '供应商账单导入', analytics: '数据统计', 'system-settings': '系统设置',
  'label-template-settings': '面单模板设置',
};
const menuItems: MenuProps['items'] = [
  { key: 'orders', icon: <FileTextOutlined />, label: '订单管理', children: [{ key: 'order-list', label: '订单列表' }, { key: 'order-create', label: '创建运单' }, { key: 'order-import', label: 'Excel 导入' }] },
  { key: 'customers', icon: <TeamOutlined />, label: '客户管理', children: [{ key: 'customer-list', label: '客户' }, { key: 'balance-alerts', label: '余额预警设置' }] },
  { key: 'products', icon: <TruckOutlined />, label: '产品与渠道', children: [{ key: 'supplier-channels', label: '供应商与渠道' }, { key: 'service-management', label: '服务管理' }] },
  { key: 'pricing', icon: <WalletOutlined />, label: '报价管理', children: [{ key: 'cost-tables', label: '供应商成本表' }, { key: 'profit-tables', label: '服务利润表' }, { key: 'remote-templates', label: '偏远地址模板' }] },
  { key: 'billing', icon: <AppstoreOutlined />, label: '账单管理', children: [{ key: 'reconciliation', label: '订单对账' }, { key: 'supplier-bills', label: '供应商账单导入' }] },
  { key: 'analytics', icon: <BarChartOutlined />, label: '数据统计' },
];

const shipmentStatusLabels: Record<string, string> = { SUBMITTED: '已下单', GENERATING: '面单生成中', GENERATED: '已生成面单', RECEIVED: '已收货', RETURNED: '已退件', CANCELLED: '已取消', FAILED: '面单生成失败', UNKNOWN: '面单生成结果未知' };
const feeStatusLabels: Record<string, string> = { PRECHARGED: '已预扣（待最终确认）', FINAL_WEIGHT_PENDING: '最终收费重待确认', RECONCILIATION_PENDING: '待会计确认', RECONCILED: '已完成对账', REFUNDED: '已退款', ADJUSTED: '已调整' };
const dispatchStatusLabels: Record<string, string> = { PENDING: '等待面单生成', VALIDATING: '正在校验', CREATING: '正在生成面单', READY: '面单已生成', FAILED: '生成失败', UNKNOWN: '生成结果未知', STALLED: '生成异常待核查', BLOCKED: '暂不支持自动打单', CANCELLED: '订单已取消' };
function shipmentStatusLabel(value: unknown) { const code = String(value ?? ''); return shipmentStatusLabels[code] ?? (code || '—'); }
function feeStatusLabel(value: unknown) { const code = String(value ?? ''); return feeStatusLabels[code] ?? (code || '—'); }
function dispatchStatusLabel(value: unknown) { const code = String(value ?? ''); return dispatchStatusLabels[code] ?? (code || '—'); }
function isPendingDispatch(order: any) { return !['READY', 'FAILED', 'UNKNOWN', 'STALLED', 'BLOCKED', 'CANCELLED'].includes(String(order.dispatch?.status ?? 'PENDING')); }

function loadTabs(): Tab[] { try { return JSON.parse(localStorage.getItem('movix.admin.tabs') ?? '') || [{ key: 'home', label: '首页' }]; } catch { return [{ key: 'home', label: '首页' }]; } }
function errorText(error: unknown) { return error instanceof Error ? error.message : '操作失败'; }
function labelFilename(label: any) { const type = String(label.contentType ?? '').toUpperCase(); const extension = type.includes('PDF') ? 'pdf' : type.includes('PNG') ? 'png' : type.includes('ZPL') ? 'zpl' : type.includes('EPL') ? 'epl' : 'bin'; return `label-${String(label.trackingNumber ?? label.id ?? 'label').replace(/[^A-Za-z0-9._-]/g, '_')}.${extension}`; }
async function asLabelBlob(response: Response) { const type = response.headers.get('content-type') ?? 'application/octet-stream'; return new Blob([await response.blob()], { type }); }
async function isPdfLabel(blob: Blob) { const header = new Uint8Array(await blob.slice(0, 4).arrayBuffer()); return blob.type.toLowerCase().includes('pdf') || String.fromCharCode(...header) === '%PDF'; }
async function downloadLabel(blob: Blob, filename: string) { const isPdf = await isPdfLabel(blob); const resolvedFilename = isPdf ? filename.replace(/\.[^.]+$/, '.pdf') : filename; const url = URL.createObjectURL(new Blob([blob], { type: isPdf ? 'application/pdf' : blob.type || 'application/octet-stream' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = resolvedFilename; document.body.appendChild(anchor); anchor.click(); anchor.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1_000); }
function escapePreviewHtml(value: string) { return value.replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char] ?? char); }
function writePreviewMessage(tab: Window, title: string, detail: string) { tab.document.open(); tab.document.write(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${escapePreviewHtml(title)}</title><style>body{margin:0;background:#f4f7fa;color:#263746;font:15px/1.6 system-ui,-apple-system,"Microsoft YaHei",sans-serif}.notice{max-width:620px;margin:12vh auto;padding:28px 32px;background:#fff;border:1px solid #dbe4ec;border-radius:12px;box-shadow:0 12px 36px #18365018}h1{font-size:20px;margin:0 0 10px}p{margin:0;color:#617283}</style></head><body><main class="notice"><h1>${escapePreviewHtml(title)}</h1><p>${escapePreviewHtml(detail)}</p></main></body></html>`); tab.document.close(); }
async function previewLabel(blob: Blob, popup?: Window | string | null) { const existing = typeof popup === 'string' ? null : popup; const tab = existing ?? window.open('', '_blank'); if (!tab) { message.error('浏览器阻止了 PDF 预览窗口，请允许弹出窗口后重试'); return false; } const bytes = new Uint8Array(await blob.slice(0, 4).arrayBuffer()); const isPdf = blob.type.toLowerCase().includes('pdf') || String.fromCharCode(...bytes) === '%PDF'; if (!isPdf) { writePreviewMessage(tab, '无法预览面单', '供应商返回的文件不是 PDF。请使用“下载 PDF”保存后核对，或检查供应商的面单输出格式。'); message.error('该面单不是 PDF，无法在浏览器中预览和打印'); return false; } const url = URL.createObjectURL(new Blob([blob], { type: 'application/pdf' })); tab.document.open(); tab.document.write(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>面单预览</title><style>html,body,embed{width:100%;height:100%;margin:0;border:0;background:#525659}</style></head><body><embed src="${url}" type="application/pdf" /></body></html>`); tab.document.close(); window.setTimeout(() => URL.revokeObjectURL(url), 10 * 60_000); return true; }

export function AdminApp() {
  const [token, setToken] = useState(() => localStorage.getItem('movix.admin.token') ?? '');
  const [tabs, setTabs] = useState<Tab[]>(loadTabs);
  const [active, setActive] = useState(() => localStorage.getItem('movix.admin.active-tab') ?? 'home');
  const [siderCollapsed, setSiderCollapsed] = useState(() => localStorage.getItem('movix.admin.sider-collapsed') === '1');
  const [data, setData] = useState<any>({ status: null, drivers: [], carriers: [], suppliers: [], services: [], customers: [], customerLevels: [], customerGroups: [], orders: [], countries: [], costs: [], profits: [], profitServices: [], remoteTemplates: [], bills: [], reconciliations: [], cancellationRefunds: [], alertSettings: [], alertNotifications: [], settings: null, declarationFields: null, labelTemplates: { templates: [], capabilities: [] } });
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const request = useCallback(async (path: string, options: RequestInit = {}) => {
    const response = await fetch(`${API}${path}`, { ...options, headers: { Authorization: `Bearer ${token}`, ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...options.headers } });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      const messageText = Array.isArray(body.message) ? body.message.join('；') : body.message || `请求失败（${response.status}）`;
      const detailText = Array.isArray(body.errors) ? body.errors.map((item: any) => `${item.code ? `[${item.code}] ` : ''}${item.message ?? String(item)}`).join('；') : body.errors?.message ?? '';
      const error = new Error(detailText && !String(messageText).includes(detailText) ? `${messageText}：${detailText}` : messageText) as Error & { status?: number };
      error.status = response.status;
      throw error;
    }
    return response;
  }, [token]);
  const refresh = useCallback(async () => {
    if (!token) return; setLoading(true);
    try {
      const paths = ['/admin/v1/products/fedex-relay-status', '/admin/v1/products/connector-drivers', '/admin/v1/products/carriers', '/admin/v1/products/suppliers', '/admin/v1/products/services', '/admin/v1/products/remote-templates', '/admin/v1/customers', '/admin/v1/customers/levels', '/admin/v1/customers/groups', '/admin/v1/orders', '/admin/v1/pricing/countries', '/admin/v1/pricing/cost-tables', '/admin/v1/pricing/profit-versions', '/admin/v1/pricing/profit-services', '/admin/v1/billing/imports', '/admin/v1/billing/reconciliations', '/admin/v1/billing/cancellation-refunds', '/admin/v1/balance-alerts/settings', '/admin/v1/balance-alerts/notifications', '/admin/v1/settings/me', '/admin/v1/settings/declaration-fields', '/admin/v1/settings/label-templates'];
      const result = await Promise.all(paths.map(async (path) => (await request(path)).json()));
      const [status, drivers, carriers, suppliers, services, remoteTemplates, customers, customerLevels, customerGroups, orders, countries, costs, profits, profitServices, bills, reconciliations, cancellationRefunds, alertSettings, alertNotifications, settings, declarationFields, labelTemplates] = result;
      setData({ status, drivers, carriers, suppliers, services, remoteTemplates, customers, customerLevels, customerGroups, orders, countries, costs, profits, profitServices, bills, reconciliations, cancellationRefunds, alertSettings, alertNotifications, settings, declarationFields, labelTemplates });
      if (settings.hasAvatar) {
        const avatar = await request('/admin/v1/settings/avatar');
        const nextUrl = URL.createObjectURL(await avatar.blob());
        setAvatarUrl((current) => { if (current) URL.revokeObjectURL(current); return nextUrl; });
      } else setAvatarUrl((current) => { if (current) URL.revokeObjectURL(current); return null; });
    } catch (error) { message.error(errorText(error)); } finally { setLoading(false); }
  }, [request, token]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => localStorage.setItem('movix.admin.tabs', JSON.stringify(tabs)), [tabs]);
  useEffect(() => localStorage.setItem('movix.admin.active-tab', active), [active]);
  useEffect(() => localStorage.setItem('movix.admin.sider-collapsed', siderCollapsed ? '1' : '0'), [siderCollapsed]);
  const completeLogin = (value: string) => {
    if (!value) { message.error('登录响应缺少访问令牌'); return; }
    localStorage.setItem('movix.admin.token', value);
    setToken(value);
  };
  if (!token) return <Login onSuccess={completeLogin} />;
  const open = (key: string) => { const label = key.startsWith('cost-table:') ? '成本表详情' : key.startsWith('profit-service:') ? '服务利润详情' : labels[key] ?? key; setTabs((current) => current.some((tab) => tab.key === key) ? current : [...current, { key, label }]); setActive(key); };
  const close = (key: string) => { setTabs((current) => current.filter((tab) => tab.key !== key)); if (active === key) setActive('home'); };
  const logout = () => { localStorage.removeItem('movix.admin.token'); localStorage.removeItem('movix.admin.tabs'); localStorage.removeItem('movix.admin.active-tab'); setToken(''); setTabs([{ key: 'home', label: '首页' }]); setActive('home'); };
  const context: Context = { data, request, refresh, logout };
  const accountMenu = { items: [{ key: 'settings', label: '系统设置', onClick: () => open('system-settings') }, { type: 'divider' as const }, { key: 'logout', icon: <LogoutOutlined />, label: '退出登录', onClick: logout }] };
  return <Layout className="admin-layout"><Sider width={244} collapsedWidth={72} collapsed={siderCollapsed} trigger={null} className="admin-sider"><div className="brand"><span className="brand-mark">M</span><span className="brand-name">MOVIX FREIGHT</span><Button className="sider-toggle" type="text" icon={siderCollapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />} aria-label={siderCollapsed ? '展开导航栏' : '收起导航栏'} title={siderCollapsed ? '展开导航栏' : '收起导航栏'} onClick={() => setSiderCollapsed((value) => !value)} /></div><div className="rail-caption">OPERATIONS WORKSPACE</div><Menu mode="inline" inlineCollapsed={siderCollapsed} items={menuItems} onClick={({ key }) => open(String(key))} className="admin-menu" /></Sider><Layout><Header className="system-header"><Space><span className="header-note">渠道区分承运商，供应商连接区分账号与环境</span></Space><Dropdown menu={accountMenu} trigger={['click']}><Button type="text" aria-label="管理员账户菜单"><Avatar src={avatarUrl ?? undefined}>{data.settings?.displayName?.slice(0, 1)?.toUpperCase() ?? 'M'}</Avatar></Button></Dropdown></Header><div className="tab-strip"><Button type="text" icon={<HomeOutlined />} onClick={() => setActive('home')} />{tabs.map((tab) => <button className={`workspace-tab ${tab.key === active ? 'active' : ''}`} key={tab.key} onClick={() => setActive(tab.key)}>{tab.label}{tab.key !== 'home' && <span className="tab-close" onClick={(e) => { e.stopPropagation(); close(tab.key); }}>×</span>}</button>)}</div><Content className="workspace-content"><Spin spinning={loading}>{renderPage(active, context, open)}</Spin></Content></Layout></Layout>;
}

function renderPage(key: string, context: Context, open: (key: string) => void) {
  if (key === 'home') return <Home status={context.data.status} open={open} />;
  if (key === 'supplier-channels') return <SupplierChannels {...context} />;
  if (key === 'service-management') return <ServiceManagement {...context} />;
  if (key === 'customer-list') return <Customers {...context} />;
  if (key === 'order-create') return <CreateOrderFlow {...context} />;
  if (key === 'order-list') return <OrderListManagement {...context} />;
  if (key === 'cost-tables') return <CostTables {...context} open={open} />;
  if (key.startsWith('cost-table:')) return <CostTableDetail {...context} tableId={key.slice('cost-table:'.length)} />;
  if (key === 'profit-tables') return <ProfitTables {...context} open={open} />;
  if (key.startsWith('profit-service:')) return <ProfitServiceDetail {...context} serviceId={key.slice('profit-service:'.length)} />;
  if (key === 'supplier-bills') return <SupplierBillsManagement {...context} />;
  if (key === 'reconciliation') return <ReconciliationManagement {...context} />;
  if (key === 'order-import') return <ExcelOrderImport {...context} />;
  if (key === 'balance-alerts') return <BalanceAlerts {...context} />;
  if (key === 'remote-templates') return <RemoteTemplates {...context} />;
  if (key === 'system-settings') return <SystemSettings {...context} open={open} />;
  if (key === 'label-template-settings') return <LabelTemplateSettings {...context} />;
  return <FrameworkPage title={labels[key]} note="该模块已保留在正式信息架构中，将按既定计划逐步接入功能。" />;
}

function Login({ onSuccess }: { onSuccess: (token: string) => void }) { const [busy, setBusy] = useState(false); const submit = async (value: any) => { setBusy(true); try { const response = await fetch(`${API}/auth/admin/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(value) }); const body = await response.json(); if (!response.ok) throw new Error(body.message || '登录失败'); onSuccess(body.accessToken); } catch (error) { message.error(errorText(error)); } finally { setBusy(false); } }; return <main className="login-page"><section className="login-panel"><div className="login-mark">M</div><Typography.Title>Movix Freight 管理端</Typography.Title><Typography.Paragraph>订单、客户、渠道、报价与账单的统一运营工作区。</Typography.Paragraph><Form layout="vertical" onFinish={submit}><Form.Item name="username" label="用户名" rules={[{ required: true }]}><Input autoFocus /></Form.Item><Form.Item name="password" label="密码" rules={[{ required: true }]}><Input.Password /></Form.Item><Button type="primary" htmlType="submit" loading={busy} block>登录</Button></Form></section></main>; }
function SystemSettings({ data, request, refresh, logout, open }: Context & { open: (key: string) => void }) {
  const [passwordForm] = Form.useForm(); const [declarationOpen, setDeclarationOpen] = useState(false); const [requiredCodes, setRequiredCodes] = useState<string[]>([]); const [saving, setSaving] = useState(false);
  const fields = data.declarationFields?.fields ?? []; const isSuperAdmin = data.settings?.roles?.includes('SUPER_ADMIN');
  useEffect(() => setRequiredCodes(fields.filter((field: any) => field.required).map((field: any) => field.code)), [data.declarationFields]);
  const uploadAvatar = async (file: File) => {
    if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) { message.error('头像仅支持 PNG、JPG 或 WebP'); return false; }
    if (file.size > 2 * 1024 * 1024) { message.error('头像大小不能超过 2 MB'); return false; }
    try { const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error('头像读取失败')); reader.readAsDataURL(file); }); await request('/admin/v1/settings/avatar', { method: 'POST', body: JSON.stringify({ mimeType: file.type, contentBase64: dataUrl.split(',')[1] }) }); message.success('头像已更新'); await refresh(); } catch (error) { message.error(errorText(error)); }
    return false;
  };
  const changePassword = async (value: any) => { try { setSaving(true); await request('/admin/v1/settings/password', { method: 'PUT', body: JSON.stringify({ currentPassword: value.currentPassword, newPassword: value.newPassword }) }); message.success('密码已修改，请重新登录'); logout(); } catch (error) { message.error(errorText(error)); } finally { setSaving(false); } };
  const saveFields = async () => { try { setSaving(true); await request('/admin/v1/settings/declaration-fields', { method: 'PUT', body: JSON.stringify({ requiredCodes }) }); message.success('申报必填规则已保存'); setDeclarationOpen(false); await refresh(); } catch (error) { message.error(errorText(error)); } finally { setSaving(false); } };
  return <section className="workspace-panel"><Typography.Title level={2}>系统设置</Typography.Title><Typography.Paragraph type="secondary">设置仅影响当前管理员账户；申报信息设置与面单模板设置为全局规则，由超级管理员统一维护。</Typography.Paragraph><Row gutter={20}><Col xs={24} lg={10}><Card title="个人资料"><Space direction="vertical" size={16} style={{ width: '100%' }}><Space><Avatar size={64}>{data.settings?.displayName?.slice(0, 1)?.toUpperCase() ?? 'M'}</Avatar><div><b>{data.settings?.displayName ?? data.settings?.username ?? '管理员'}</b><br /><Typography.Text type="secondary">{data.settings?.username}</Typography.Text></div></Space><Upload accept="image/png,image/jpeg,image/webp" showUploadList={false} beforeUpload={uploadAvatar}><Button>上传头像</Button></Upload><Typography.Text type="secondary">支持 PNG、JPG、WebP，最大 2 MB。</Typography.Text></Space></Card></Col><Col xs={24} lg={14}><Card title="修改本人密码"><Form form={passwordForm} layout="vertical" onFinish={changePassword}><Row gutter={12}><Col span={8}><Form.Item name="currentPassword" label="当前密码" rules={[{ required: true }]}><Input.Password /></Form.Item></Col><Col span={8}><Form.Item name="newPassword" label="新密码" rules={[{ required: true, min: 8, message: '新密码至少 8 位' }]}><Input.Password /></Form.Item></Col><Col span={8}><Form.Item name="confirmPassword" label="确认新密码" dependencies={['newPassword']} rules={[{ required: true }, ({ getFieldValue }) => ({ validator: (_, value) => !value || getFieldValue('newPassword') === value ? Promise.resolve() : Promise.reject(new Error('两次输入的新密码不一致')) })]}><Input.Password /></Form.Item></Col></Row><Button type="primary" htmlType="submit" loading={saving}>保存密码并退出登录</Button></Form></Card></Col></Row>{isSuperAdmin && <><Card title="申报信息设置" style={{ marginTop: 20 }} extra={<Button type="primary" onClick={() => setDeclarationOpen(true)}>配置必填字段</Button>}><Typography.Paragraph style={{ marginBottom: 0 }}>基础箱号字段始终必填。勾选的申报字段会在管理员下单、客户下单和 Excel 导入中显示红色星号并强制校验；FedEx 服务还会额外强制其接口所需字段。</Typography.Paragraph></Card><Card title="面单模板设置" style={{ marginTop: 20 }} extra={<Button type="primary" onClick={() => open('label-template-settings')}>打开模板设置</Button>}><Typography.Paragraph style={{ marginBottom: 0 }}>按供应商连接选择面单规格并设计热敏自定义区域。可实时预览，并使用浏览器“打印/另存为 PDF”检查设计效果；仅供应商驱动已确认支持的参数才会随正式订单下发。</Typography.Paragraph></Card></>}<Modal open={declarationOpen} title="申报信息设置" okText="保存规则" confirmLoading={saving} onOk={() => void saveFields()} onCancel={() => setDeclarationOpen(false)}><Typography.Paragraph type="secondary">勾选即为全局必填。锁定字段用于计费和承运商请求，不能取消。</Typography.Paragraph><Space direction="vertical" style={{ width: '100%' }}>{fields.map((field: any) => <Checkbox key={field.code} checked={requiredCodes.includes(field.code)} disabled={field.locked} onChange={(event) => setRequiredCodes((current) => event.target.checked ? [...new Set([...current, field.code])] : current.filter((code) => code !== field.code))}>{field.label}{field.locked && <Typography.Text type="secondary">（锁定必填）</Typography.Text>}</Checkbox>)}</Space></Modal></section>;
}

const labelStockOptions: Record<string, string[]> = { PDF: ['PAPER_4X6', 'PAPER_4X675', 'PAPER_4X8', 'PAPER_4X9'], PNG: ['PAPER_4X6', 'PAPER_4X675', 'PAPER_4X8', 'PAPER_4X9'], ZPLII: ['STOCK_4X6', 'STOCK_4X8', 'STOCK_4X9'], EPL2: ['STOCK_4X6', 'STOCK_4X8', 'STOCK_4X9'] };
const previewFieldValues: Record<string, string> = { order_no: 'ORD-20260824-001', client_reference: 'ERP-REF-001', box_no: 'FBA-BOX-001', recipient_name: 'JANE DOE', recipient_postcode: '1012JS', customer_no: 'CUS-000001' };

function LabelTemplateSettings({ data, request, refresh }: Context) {
  const [form] = Form.useForm(); const [selectedId, setSelectedId] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  const outputFormat = Form.useWatch('outputFormat', form) ?? 'PDF'; const labelStockType = Form.useWatch('labelStockType', form) ?? 'PAPER_4X6'; const supplierId = Form.useWatch('supplierId', form); const elements = Form.useWatch('customElements', form) ?? [];
  const suppliers = data.suppliers ?? []; const templates = data.labelTemplates?.templates ?? []; const selectedSupplier = suppliers.find((item: any) => item.id === supplierId); const capability = (data.labelTemplates?.capabilities ?? []).find((item: any) => item.driverCode === selectedSupplier?.driverCode);
  const isUpsTemplate = selectedSupplier?.driverCode === 'UPS_OFFICIAL';
  useEffect(() => { if (isUpsTemplate) form.setFieldsValue({ outputFormat: 'PDF', labelStockType: 'PAPER_4X6', thermalDpi: null, customElements: [] }); }, [isUpsTemplate, form]);
  const thermalCustom = ['ZPLII', 'EPL2'].includes(outputFormat) && ['STOCK_4X8', 'STOCK_4X9'].includes(labelStockType);
  const reset = () => { setSelectedId(null); form.setFieldsValue({ supplierId: undefined, name: '未命名面单模板', outputFormat: 'PDF', labelStockType: 'PAPER_4X6', thermalDpi: null, customElements: [], enabled: true, applyToCarrier: false }); };
  const openTemplate = (template: any) => { setSelectedId(template.id); form.setFieldsValue({ ...template, customElements: template.customElements ?? [] }); };
  const changeFormat = (value: string) => { const stock = labelStockOptions[value]?.[0]; form.setFieldsValue({ outputFormat: value, labelStockType: stock, thermalDpi: ['ZPLII', 'EPL2'].includes(value) ? 203 : null, ...(value === 'PDF' || value === 'PNG' ? { customElements: [] } : {}) }); };
  const save = async (value: any) => { try { setBusy(true); const body = { ...value, thermalDpi: ['ZPLII', 'EPL2'].includes(value.outputFormat) ? Number(value.thermalDpi) : null, customElements: (value.customElements ?? []).map((item: any, index: number) => ({ ...item, id: item.id || `element-${index + 1}`, xMm: Number(item.xMm), yMm: Number(item.yMm), widthMm: item.widthMm == null || item.widthMm === '' ? undefined : Number(item.widthMm), heightMm: item.heightMm == null || item.heightMm === '' ? undefined : Number(item.heightMm), fontSize: item.fontSize == null || item.fontSize === '' ? undefined : Number(item.fontSize) })) };
      if (selectedId) await request(`/admin/v1/settings/label-templates/${selectedId}`, { method: 'PUT', body: JSON.stringify(body) }); else { const response = await request('/admin/v1/settings/label-templates', { method: 'POST', body: JSON.stringify(body) }); const created = await response.json(); setSelectedId(created.id); }
      message.success('面单模板已保存'); await refresh();
    } catch (error) { message.error(errorText(error)); } finally { setBusy(false); } };
  const printable = () => { const proof = document.querySelector('[data-label-template-proof]') as HTMLElement | null; if (!proof) return; const popup = window.open('', '_blank', 'noopener,noreferrer'); if (!popup) { message.error('浏览器阻止了预览窗口，请允许弹出窗口后重试'); return; } popup.document.write(`<!doctype html><html><head><title>Movix 面单模板预览</title><style>@page{margin:8mm}body{font-family:Arial,sans-serif;background:#fff}.label-proof{width:101.6mm;border:1px solid #000;background:#fff}.label-proof-core{height:152.4mm;padding:7mm;position:relative;border-bottom:2px solid #000;color:#000}.label-proof__meta{font-size:9px;line-height:1.4}.label-proof__recipient{margin-top:13mm;font-size:19px;font-weight:800;line-height:1.18}.label-proof__route{position:absolute;bottom:8mm;left:7mm;font-size:30px;font-weight:900}.label-proof__barcode{position:absolute;right:7mm;bottom:8mm;width:35mm;height:22mm;background:repeating-linear-gradient(90deg,#000 0 1px,#fff 1px 3px,#000 3px 5px,#fff 5px 7px)}.label-proof-custom{height:50.8mm;position:relative;border-top:0;background:#f2fbfc;overflow:hidden}.label-proof-custom__hint{position:absolute;left:3mm;bottom:2mm;font-size:7px;color:#52717a}.label-proof-element{position:absolute;white-space:nowrap;overflow:hidden;color:#132f3d}.label-proof-element--barcode{height:9mm;background:repeating-linear-gradient(90deg,#000 0 1px,#fff 1px 2px,#000 2px 4px,#fff 4px 6px)}.label-proof-element--logo{display:grid;place-items:center;border:1px solid #1a6e85;background:#d8f1f2;font-size:10px;font-weight:700}</style></head><body>${proof.outerHTML}<script>window.onload=function(){window.print()}</script></body></html>`); popup.document.close(); };
  const previewText = (item: any) => item.type === 'FIELD' ? (previewFieldValues[item.value] ?? item.value) : item.type === 'LOGO' ? 'MOVIX LOGO' : item.type === 'BARCODE' ? '' : item.value;
  return <section className="workspace-panel label-template-page"><Typography.Title level={2}>面单模板设置</Typography.Title><Typography.Paragraph type="secondary">模板绑定供应商连接，而不是单个服务。标准面单规格可在支持的供应商连接上随订单下发；自定义热敏图文先作为设计稿保存，只有驱动确认字段透传能力后才会启用下发。</Typography.Paragraph><Alert className="status-alert" type="info" showIcon message="预览说明" description="预览中的 FedEx 核心区是布局示意，真实收寄件信息、路由码、条码、字体与位置由 FedEx 生成。点击“打印 / 另存为 PDF”可在浏览器中观察实际物理尺寸。" />
    <Row gutter={22}><Col xs={24} xl={13}><Card title={selectedId ? '编辑面单模板' : '新建面单模板'} extra={<Button onClick={reset}>新建空模板</Button>}><Form form={form} layout="vertical" initialValues={{ name: '未命名面单模板', outputFormat: 'PDF', labelStockType: 'PAPER_4X6', customElements: [], enabled: true }} onFinish={save}><Row gutter={12}><Col span={12}><Form.Item name="supplierId" label="供应商连接" rules={[{ required: true, message: '请选择供应商连接' }]}><Select showSearch optionFilterProp="label" options={suppliers.map((item: any) => ({ value: item.id, label: `${item.carrier?.name ?? '未知渠道'} · ${item.name} · ${item.environment}` }))} /></Form.Item></Col><Col span={12}><Form.Item name="name" label="模板名称" rules={[{ required: true }]}><Input /></Form.Item></Col></Row>{selectedSupplier && <Alert type={capability?.standardLabelSpecification ? 'success' : 'warning'} showIcon message={`${selectedSupplier.carrier?.name ?? '供应商'} · ${selectedSupplier.name}`} description={capability?.message ?? '该驱动暂无面单模板能力声明。'} style={{ marginBottom: 16 }} />}<Row gutter={12}><Col span={8}><Form.Item name="outputFormat" label="输出格式" rules={[{ required: true }]}><Select onChange={changeFormat} options={['PDF', 'PNG', 'ZPLII', 'EPL2'].map((value) => ({ value, disabled: capability && !capability.supportedOutputFormats?.includes(value) }))} /></Form.Item></Col><Col span={10}><Form.Item name="labelStockType" label="标签规格" rules={[{ required: true }]}><Select options={(isUpsTemplate ? ['PAPER_4X6'] : labelStockOptions[outputFormat] ?? []).map((value) => ({ value }))} /></Form.Item></Col><Col span={6}><Form.Item name="thermalDpi" label="热敏 DPI"><Select disabled={!['ZPLII', 'EPL2'].includes(outputFormat)} options={[{ value: 203 }, { value: 300 }]} /></Form.Item></Col></Row><Row gutter={12}><Col span={12}><Form.Item name="enabled" valuePropName="checked"><Checkbox>启用模板</Checkbox></Form.Item></Col><Col span={12}><Form.Item name="applyToCarrier" valuePropName="checked"><Checkbox disabled={!capability?.standardLabelSpecification || elements.length > 0}>将规格下发到供应商</Checkbox></Form.Item></Col></Row>{elements.length > 0 && <Alert type="warning" showIcon message="含自定义图文的模板当前仅用于预览" description="为了避免中转接口未确认的字段被忽略，此类模板不能设置为“将规格下发到供应商”。可保存后人工下单核对标准面单，或等待驱动确认后再开放自动下发。" style={{ marginBottom: 16 }} />}
      {!isUpsTemplate && <><Divider orientation="left">热敏自定义区域</Divider>{thermalCustom ? <><Typography.Paragraph type="secondary">仅 4×8 / 4×9 热敏面单可设计。可用区域最大 114.3 × 50.8 mm；坐标以自定义区域左上角为原点，系统会拦截超界元素。系统字段可填：order_no、client_reference、box_no、recipient_name、recipient_postcode、customer_no。</Typography.Paragraph><Form.List name="customElements">{(fields, { add, remove }) => <><Button size="small" icon={<PlusOutlined />} onClick={() => add({ id: `element-${fields.length + 1}`, type: 'FIELD', value: 'order_no', xMm: 5, yMm: 5, fontSize: 16 })}>添加元素</Button>{fields.map((field) => <div className="label-template-element-form" key={field.key}><Row gutter={8}><Col span={5}><Form.Item name={[field.name, 'type']} label="类型" rules={[{ required: true }]}><Select options={[{ value: 'FIELD', label: '系统字段' }, { value: 'TEXT', label: '固定文字' }, { value: 'BARCODE', label: '内部条码' }, { value: 'LOGO', label: 'Logo 占位' }]} /></Form.Item></Col><Col span={6}><Form.Item name={[field.name, 'value']} label="字段/内容" rules={[{ required: true }]}><Input placeholder="如 order_no 或 固定文字" /></Form.Item></Col><Col span={3}><Form.Item name={[field.name, 'xMm']} label="X mm" rules={[{ required: true }]}><InputNumber min={0} max={114.3} style={{ width: '100%' }} /></Form.Item></Col><Col span={3}><Form.Item name={[field.name, 'yMm']} label="Y mm" rules={[{ required: true }]}><InputNumber min={0} max={50.8} style={{ width: '100%' }} /></Form.Item></Col><Col span={3}><Form.Item name={[field.name, 'fontSize']} label="字号 px"><InputNumber min={8} max={48} style={{ width: '100%' }} /></Form.Item></Col><Col span={3}><Form.Item name={[field.name, 'widthMm']} label="宽 mm"><InputNumber min={1} max={114.3} style={{ width: '100%' }} /></Form.Item></Col><Col span={1}><Button danger type="text" icon={<DeleteOutlined />} aria-label="删除元素" onClick={() => remove(field.name)} /></Col></Row></div>)}</>}</Form.List></> : <Alert type="warning" showIcon message="当前规格没有自定义图文区域" description="请切换至 ZPLII 或 EPL2，并选择 STOCK_4X8 或 STOCK_4X9。PDF/PNG 和 4×6 热敏面单只能选择标准规格，不能改变 FedEx 核心排版。" />}</>}
      <Space style={{ marginTop: 20 }}><Button type="primary" htmlType="submit" loading={busy}>保存模板</Button><Button disabled={isUpsTemplate} onClick={printable}>打印 / 另存为 PDF</Button></Space></Form></Card><Divider orientation="left">已保存模板</Divider><Table rowKey="id" size="small" dataSource={templates} pagination={{ pageSize: 8 }} onRow={(record: any) => ({ onClick: () => openTemplate(record), style: { cursor: 'pointer' } })} columns={[{ title: '模板', dataIndex: 'name' }, { title: '渠道 / 供应商', render: (_, item: any) => `${item.supplier?.carrier?.name ?? '—'} · ${item.supplier?.name ?? '—'}` }, { title: '规格', render: (_, item: any) => `${item.outputFormat} · ${item.labelStockType}` }, { title: '状态', render: (_, item: any) => <Space><Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag>{item.applyToCarrier && <Tag color="blue">下发规格</Tag>}</Space> }]} /></Col>
      <Col xs={24} xl={11}>{isUpsTemplate ? <Alert type="info" showIcon message="UPS 固定 4×6 PDF" description="原始 GIF 无损转为 PNG 后放入 PDF，四周约 2 mm 白边；不支持自定义排版。请在真实订单详情预览与打印，不使用 FedEx 布局示意。"/> : <Card title="模板物理预览" extra={<Tag color={thermalCustom ? 'cyan' : 'default'}>{thermalCustom ? '热敏自定义区' : '标准核心区'}</Tag>}><div className="label-template-preview-wrap"><div className="label-proof" data-label-template-proof><div className="label-proof-core"><div className="label-proof__meta">FROM&nbsp;&nbsp; MOVIX FREIGHT<br />SHIP DATE: 24 AUG 2026<br />ACTWGT: 1.00 KG<br />DIMS: 20 × 15 × 10 CM</div><div className="label-proof__recipient">TO<br />JANE DOE<br />DAM 1<br /><br />AMSTERDAM NH 1012 (NL)</div><div className="label-proof__reference">REF: {previewFieldValues.order_no}</div><div className="label-proof__route">9A AMSA</div><div className="label-proof__barcode" /></div>{thermalCustom && <div className="label-proof-custom">{elements.map((item: any, index: number) => <div className={`label-proof-element label-proof-element--${String(item.type ?? '').toLowerCase()}`} key={item.id ?? index} style={{ left: `${Math.min(Math.max(Number(item.xMm) || 0, 0), 114.3) / 114.3 * 100}%`, top: `${Math.min(Math.max(Number(item.yMm) || 0, 0), 50.8) / 50.8 * 100}%`, fontSize: `${Math.min(Math.max(Number(item.fontSize) || 14, 8), 48)}px`, width: item.widthMm ? `${Math.min(Number(item.widthMm), 114.3) / 114.3 * 100}%` : undefined }}>{previewText(item)}</div>)}<span className="label-proof-custom__hint">可编辑热敏区域 · 最大 114.3 × 50.8 mm</span></div>}</div></div><Typography.Paragraph type="secondary" style={{ marginTop: 16, marginBottom: 0 }}>此预览用于核对模板元素的相对位置。真实 FedEx 面单核心区、条码和分拣码以供应商响应为准，不能由模板修改。</Typography.Paragraph></Card>}</Col></Row>
  </section>;
}

function Home({ status, open }: any) { return <section className="workspace-panel runway"><div><span className="eyebrow">MOVIX FREIGHT / OPERATIONS</span><Typography.Title>从服务配置到面单交付。</Typography.Title><Typography.Paragraph>尾程渠道区分 FedEx、UPS、DPD 等承运商；供应商连接管理各账号、环境与接口，订单、报价和账单均使用同一套正式流程。</Typography.Paragraph><Space wrap><Button type="primary" onClick={() => open('order-list')}>查看订单</Button><Button onClick={() => open('supplier-channels')}>管理供应商与渠道</Button><Button onClick={() => open('service-management')}>管理服务</Button></Space></div><div className="runway-status"><b>{status?.configured ? 'READY' : 'HOLD'}</b><span>{status?.configured ? `FedEx 连接环境：${status.environment?.toUpperCase()}` : 'FedEx 连接配置尚未就绪'}</span></div></section>; }
function FrameworkPage({ title, note }: { title: string; note: string }) { return <section className="workspace-panel"><Typography.Title level={2}>{title}</Typography.Title><Alert type="info" showIcon message={note} /></section>; }
function post(request: Context['request'], refresh: Context['refresh'], path: string, body: unknown) { return request(path, { method: 'POST', body: JSON.stringify(body) }).then(async () => { message.success('已保存'); await refresh(); }).catch((error) => message.error(errorText(error))); }

function BalanceAlerts({ data, request, refresh }: Context) {
  const [values, setValues] = useState({ eurThreshold: '0.00', gbpThreshold: '0.00' });
  useEffect(() => { const setting = (currency: string) => (data.alertSettings ?? []).find((item: any) => item.currency === currency)?.threshold ?? '0.00'; setValues({ eurThreshold: String(setting('EUR')), gbpThreshold: String(setting('GBP')) }); }, [data.alertSettings]);
  const save = async () => { try { await request('/admin/v1/balance-alerts/settings', { method: 'POST', body: JSON.stringify(values) }); message.success('余额预警阈值已保存'); await refresh(); } catch (error) { message.error(errorText(error)); } };
  return <section className="workspace-panel"><Typography.Title level={2}>余额预警设置</Typography.Title><Typography.Paragraph type="secondary">阈值为全局规则，EUR 与 GBP 分开管理。客户任一钱包首次进入低余额区间时，系统会分别创建管理员和客户的站内消息；余额恢复后自动关闭本次预警状态。</Typography.Paragraph><Row gutter={18}><Col span={12}><Card className="threshold-card threshold-card--eur" title="EUR 余额阈值" extra={<Tag color="blue">欧元</Tag>}><Input prefix="EUR" value={values.eurThreshold} onChange={(event) => setValues({ ...values, eurThreshold: event.target.value })} /><Typography.Paragraph type="secondary" style={{ marginTop: 12, marginBottom: 0 }}>当 EUR 余额小于或等于此金额时触发预警。</Typography.Paragraph></Card></Col><Col span={12}><Card className="threshold-card threshold-card--gbp" title="GBP 余额阈值" extra={<Tag color="purple">英镑</Tag>}><Input prefix="GBP" value={values.gbpThreshold} onChange={(event) => setValues({ ...values, gbpThreshold: event.target.value })} /><Typography.Paragraph type="secondary" style={{ marginTop: 12, marginBottom: 0 }}>阈值不影响另一币种的钱包或服务下单资格。</Typography.Paragraph></Card></Col></Row><Space style={{ marginTop: 18 }}><Button type="primary" onClick={() => void save()}>保存全局阈值</Button></Space><Divider orientation="left">最近站内预警消息</Divider><Table rowKey="id" dataSource={data.alertNotifications} pagination={{ pageSize: 10 }} columns={[{ title: '对象', render: (_, item: any) => item.audience === 'ADMIN' ? '管理员' : `${item.customer?.customerNo ?? ''} · ${item.customer?.username ?? '客户'}` }, { title: '币种', dataIndex: 'currency', render: (value) => <Tag>{value}</Tag> }, { title: '标题', dataIndex: 'title' }, { title: '内容', dataIndex: 'content' }, { title: '时间', dataIndex: 'createdAt', render: (value) => new Date(value).toLocaleString() }]} /></section>;
}

function RemoteTemplates({ data, request, refresh }: Context) {
  const [bindingForm] = Form.useForm();
  const templates = data.remoteTemplates ?? [];
  const createTemplate = async (value: any) => {
    try {
      const rules = (value.rules ?? []).map((rule: any) => ({ countryCode: String(rule.countryCode ?? '').trim().toUpperCase(), ruleType: rule.ruleType, ruleValue: String(rule.ruleValue ?? '').trim().toUpperCase().replaceAll(' ', '') }));
      await request('/admin/v1/products/remote-templates', { method: 'POST', body: JSON.stringify({ ...value, rules }) });
      message.success('偏远地址模板已创建');
      await refresh();
    } catch (error) { message.error(errorText(error)); }
  };
  const saveBinding = async (value: any) => {
    try {
      await request(`/admin/v1/products/services/${value.serviceId}/remote-config`, { method: 'PATCH', body: JSON.stringify({ remoteFeeEnabled: value.remoteFeeEnabled, remoteFeeAmount: value.remoteFeeEnabled ? value.remoteFeeAmount : undefined, remoteAreaTemplateId: value.remoteFeeEnabled ? value.remoteAreaTemplateId : undefined }) });
      message.success('服务偏远费设置已保存');
      bindingForm.resetFields();
      await refresh();
    } catch (error) { message.error(errorText(error)); }
  };
  return <section className="workspace-panel">
    <Typography.Title level={2}>偏远地址模板</Typography.Title>
    <Typography.Paragraph type="secondary">模板定义欧洲目的国的邮编命中范围。服务最多绑定一个模板；仅当服务启用偏远费、已绑定模板且收件国家与邮编命中规则时，报价才加入该服务的偏远费用。</Typography.Paragraph>
    <Alert className="status-alert" type="info" showIcon message="规则支持精确邮编和邮编前缀" description="系统会自动忽略邮编中的空格并转为大写。例如 GB / PREFIX / AB10 会命中 AB10 及其后续邮编；NL / EXACT / 1012JS 仅命中该邮编。" />
    <Row gutter={20}>
      <Col span={12}><Card title="新建偏远地址模板">
        <Form layout="vertical" initialValues={{ rules: [{ countryCode: 'GB', ruleType: 'PREFIX' }] }} onFinish={createTemplate}>
          <Row gutter={12}><Col span={10}><Form.Item name="code" label="模板编号" rules={[{ required: true }]}><Input placeholder="UK_REMOTE" /></Form.Item></Col><Col span={14}><Form.Item name="name" label="模板名称" rules={[{ required: true }]}><Input placeholder="英国偏远地区" /></Form.Item></Col></Row>
          <Form.Item name="description" label="说明"><Input.TextArea rows={2} placeholder="可选，用于说明适用范围" /></Form.Item>
          <Form.List name="rules">{(fields, { add, remove }) => <><div className="remote-template__rules-title"><span>邮编规则</span><Button size="small" icon={<PlusOutlined />} onClick={() => add({ ruleType: 'PREFIX' })}>新增规则</Button></div>{fields.map((field) => <div className="remote-rule-row" key={field.key}><Form.Item name={[field.name, 'countryCode']} rules={[{ required: true, pattern: /^[A-Za-z]{2}$/, message: '填写两位国家代码' }]}><Input placeholder="GB" maxLength={2} /></Form.Item><Form.Item name={[field.name, 'ruleType']} rules={[{ required: true }]}><Select options={[{ value: 'EXACT', label: '精确邮编' }, { value: 'PREFIX', label: '邮编前缀' }]} /></Form.Item><Form.Item name={[field.name, 'ruleValue']} rules={[{ required: true, message: '填写邮编或前缀' }]}><Input placeholder="AB10" /></Form.Item><Button danger type="text" icon={<DeleteOutlined />} aria-label="删除邮编规则" disabled={fields.length === 1} onClick={() => remove(field.name)} /></div>)}</>}</Form.List>
          <Button type="primary" htmlType="submit">创建模板</Button>
        </Form>
      </Card></Col>
      <Col span={12}><Card title="绑定服务偏远费">
        <Form form={bindingForm} layout="vertical" initialValues={{ remoteFeeEnabled: true }} onFinish={saveBinding}>
          <Form.Item name="serviceId" label="服务" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.services ?? []).map((service: any) => ({ value: service.id, label: `${service.code} · ${service.name}${service.remoteFeeEnabled ? '（已启用）' : ''}` }))} /></Form.Item>
          <Form.Item name="remoteFeeEnabled" label="是否收取偏远费" rules={[{ required: true }]}><Select options={[{ value: true, label: '启用' }, { value: false, label: '不启用并清除绑定' }]} /></Form.Item>
          <Row gutter={12}><Col span={12}><Form.Item name="remoteFeeAmount" label="偏远费用"><Input placeholder="启用时必填，例如 12.50" /></Form.Item></Col><Col span={12}><Form.Item name="remoteAreaTemplateId" label="偏远地址模板"><Select allowClear placeholder="启用时选择模板" options={templates.filter((template: any) => template.enabled).map((template: any) => ({ value: template.id, label: `${template.code} · ${template.name}` }))} /></Form.Item></Col></Row>
          <Button type="primary" htmlType="submit">保存服务设置</Button>
        </Form>
      </Card></Col>
    </Row>
    <Divider orientation="left">已配置模板</Divider>
    <Table rowKey="id" dataSource={templates} pagination={{ pageSize: 10 }} locale={{ emptyText: '尚未创建偏远地址模板' }} expandable={{ expandedRowRender: (template: any) => <Table rowKey="id" size="small" pagination={false} dataSource={template.rules} columns={[{ title: '国家', dataIndex: 'countryCode' }, { title: '匹配方式', dataIndex: 'ruleType', render: (value) => <Tag color={value === 'EXACT' ? 'blue' : 'cyan'}>{value === 'EXACT' ? '精确邮编' : '邮编前缀'}</Tag> }, { title: '规则值', dataIndex: 'ruleValue' }]} /> }} columns={[{ title: '模板', render: (_, template: any) => <><b>{template.code}</b><br /><Typography.Text type="secondary">{template.name}</Typography.Text></> }, { title: '规则数', render: (_, template: any) => template.rules?.length ?? 0 }, { title: '已绑定服务', render: (_, template: any) => template._count?.services ?? 0 }, { title: '说明', dataIndex: 'description', render: (value) => value || '—' }, { title: '状态', render: (_, template: any) => <Tag color={template.enabled ? 'green' : 'default'}>{template.enabled ? '启用' : '停用'}</Tag> }]} />
  </section>;
}

function SupplierChannels({ data, request, refresh }: Context) {
  const [supplierForm] = Form.useForm();
  const [fuelForm] = Form.useForm();
  const [routeForm] = Form.useForm();
  const [detail, setDetail] = useState<any>(null);
  const [routeEditing, setRouteEditing] = useState<any>(null);
  const [carrierDetail, setCarrierDetail] = useState<any>(null);
  const [carrierToRemove, setCarrierToRemove] = useState<any>(null);
  const [removingCarrier, setRemovingCarrier] = useState(false);
  const driverCode = Form.useWatch('driverCode', supplierForm);
  const editingRouteType = Form.useWatch('routeType', routeForm);
  const selectedDriver = (data.drivers ?? []).find((item: any) => item.code === driverCode);
  const fedexEnabledServices = (detail?.services ?? []).filter((service: any) => service.enabled);
  const fedexUnifiedService = fedexEnabledServices.length === 1 ? fedexEnabledServices[0] : null;
  const submitCarrier = async (value: any) => {
    try { await request('/admin/v1/products/carriers', { method: 'POST', body: JSON.stringify(value) }); message.success('尾程渠道已创建'); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  const submitSupplier = async (value: any) => {
    try { await request('/admin/v1/products/suppliers', { method: 'POST', body: JSON.stringify(value) }); message.success('供应商连接已创建'); supplierForm.resetFields(); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  const removeCarrier = (carrier: any) => setCarrierToRemove(carrier);
  const confirmRemoveCarrier = async () => {
    if (!carrierToRemove) return;
    try { setRemovingCarrier(true); await request(`/admin/v1/products/carriers/${carrierToRemove.id}`, { method: 'DELETE' }); message.success('尾程渠道已删除'); setCarrierToRemove(null); await refresh(); }
    catch (error) { if ((error as { status?: number }).status === 404) { message.info('该尾程渠道已删除，已刷新列表'); setCarrierToRemove(null); await refresh(); } else message.error(errorText(error)); }
    finally { setRemovingCarrier(false); }
  };
  const openDetail = async (supplierId: string) => { try { setDetail(await (await request(`/admin/v1/products/suppliers/${supplierId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  const openCarrierDetail = async (carrierId: string) => { try { fuelForm.resetFields(); setCarrierDetail(await (await request(`/admin/v1/products/carriers/${carrierId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  const saveFuelSurcharge = async (value: any) => {
    if (!carrierDetail) return;
    try { await request(`/admin/v1/products/carriers/${carrierDetail.id}/fuel-surcharges`, { method: 'POST', body: JSON.stringify(value) }); message.success('渠道燃油费率已保存'); fuelForm.resetFields(); await refresh(); setCarrierDetail(await (await request(`/admin/v1/products/carriers/${carrierDetail.id}`)).json()); }
    catch (error) { message.error(errorText(error)); }
  };
  const deleteFuelSurcharge = async (surchargeId: string) => {
    if (!carrierDetail) return;
    try { await request(`/admin/v1/products/carriers/${carrierDetail.id}/fuel-surcharges/${surchargeId}`, { method: 'DELETE' }); message.success('渠道燃油费率已删除'); await refresh(); setCarrierDetail(await (await request(`/admin/v1/products/carriers/${carrierDetail.id}`)).json()); }
    catch (error) { message.error(errorText(error)); }
  };
  const saveDetail = async (value: any) => {
    if (!detail) return;
    try { const response = await request(`/admin/v1/products/suppliers/${detail.id}`, { method: 'PATCH', body: JSON.stringify(value) }); setDetail(await response.json()); message.success('供应商连接已更新'); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  const setEnabled = async (enabled: boolean) => {
    if (!detail) return;
    try { const response = await request(`/admin/v1/products/suppliers/${detail.id}/enabled`, { method: 'PATCH', body: JSON.stringify({ enabled }) }); setDetail(await response.json()); message.success(enabled ? '供应商连接已启用' : '供应商连接已停用'); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  const remove = () => {
    if (!detail) return;
    Modal.confirm({ title: '删除供应商连接', content: '仅未被服务、成本表或账单引用的连接可以删除。', okType: 'danger', onOk: async () => {
      try { await request(`/admin/v1/products/suppliers/${detail.id}`, { method: 'DELETE' }); message.success('供应商连接已删除'); setDetail(null); await refresh(); }
      catch (error) { message.error(errorText(error)); }
    } });
  };
  const openRouteEditor = (route?: any) => {
    setRouteEditing(route ?? {});
    routeForm.setFieldsValue(route ? { enabled: true, ...route, countryCodes: route.countryCodes ?? (route.countries ?? []).map((item: any) => item.countryCode) } : { routeType: detail?.driverCode === 'FEDEX_RELAY' ? 'PAN_EUROPE' : 'DEFAULT', customsMode: detail?.driverCode === 'FEDEX_RELAY' ? 'COMMODITIES' : 'NONE', enabled: true, countryCodes: [] });
  };
  const saveRoute = async (value: any) => {
    if (!detail) return;
    try {
      const path = routeEditing?.id ? `/admin/v1/products/suppliers/${detail.id}/country-routes/${routeEditing.id}` : `/admin/v1/products/suppliers/${detail.id}/country-routes`;
      const fedexPreset = detail.driverCode === 'FEDEX_RELAY' ? value.routeType === 'NL_DOMESTIC'
        ? { carrierServiceType: 'FEDEX_PRIORITY', customsMode: 'NONE', countryCodes: ['NL'] }
        : { carrierServiceType: 'FEDEX_REGIONAL_ECONOMY', customsMode: 'COMMODITIES' } : detail.driverCode === 'UPS_OFFICIAL' ? { carrierServiceType: '11', customsMode: 'NONE', routeType: 'DEFAULT' } : {};
      await request(path, { method: routeEditing?.id ? 'PATCH' : 'POST', body: JSON.stringify({ ...value, ...fedexPreset }) });
      message.success(routeEditing?.id ? '国家路由已更新' : '国家路由已创建'); setRouteEditing(null); routeForm.resetFields(); await openDetail(detail.id); await refresh();
    } catch (error) { message.error(errorText(error)); }
  };
  const removeRoute = (route: any) => Modal.confirm({ title: '删除国家路由', content: `将删除“${route.name}”。存在历史订单引用时系统会拒绝删除。`, okType: 'danger', onOk: async () => { try { await request(`/admin/v1/products/suppliers/${detail.id}/country-routes/${route.id}`, { method: 'DELETE' }); message.success('国家路由已删除'); await openDetail(detail.id); await refresh(); } catch (error) { message.error(errorText(error)); } } });
  const fieldControl = (field: any) => field.type === 'MULTI_SELECT'
    ? <Select mode="multiple" options={field.options} />
    : field.type === 'SELECT' ? <Select options={field.options} />
      : field.type === 'BOOLEAN' ? <Select options={[{ value: true, label: '是' }, { value: false, label: '否' }]} /> : <Input />;
  return <section className="workspace-panel">
    <Typography.Title level={2}>供应商与渠道</Typography.Title>
    <Typography.Paragraph type="secondary">关系：尾程渠道（FedEx / UPS / DPD）→ 供应商连接（账号、环境、接口）→ 服务。密钥、账号和 URL 只由本地连接配置文件保存，页面不会显示其原文。</Typography.Paragraph>
    <Alert className="status-alert" type="info" showIcon message="凭据按供应商连接独立配置" description="请在供应商详情查看对应编号的配置状态；本地配置完整不代表承运商账号已获线路授权。" />
    <Card title="接口列表" style={{ marginBottom: 18 }}>
      <Table rowKey="code" size="small" pagination={false} dataSource={data.drivers ?? []} columns={[
        { title: '接口驱动', render: (_, item: any) => <><b>{item.code}</b><br /><Typography.Text type="secondary">{item.name}</Typography.Text></> },
        { title: '兼容尾程渠道', render: (_, item: any) => item.carrierCodes?.map((code: string) => <Tag key={code}>{code}</Tag>) },
        { title: '支持能力', dataIndex: 'description' },
        { title: '凭据状态', render: (_, item: any) => item.connections?.length ? item.connections.map((connection: any) => <Tag key={connection.code} color={connection.configured ? 'green' : 'orange'}>{connection.name}：{connection.configured ? '就绪' : connection.environmentMatches === false ? '环境不匹配/缺配置' : '未配置或不完整'}</Tag>) : <Tag>尚无供应商连接</Tag> },
      ]} />
    </Card>
    <Row gutter={20}>
      <Col span={8}><Card title="新增尾程渠道"><Typography.Paragraph type="secondary">仅填写名称，系统自动生成不可变内部编号。</Typography.Paragraph><Form layout="vertical" onFinish={submitCarrier}><Form.Item name="name" label="渠道名称" rules={[{ required: true, message: '请填写例如 FedEx、UPS、DPD' }]}><Input placeholder="FedEx" /></Form.Item><Button type="primary" htmlType="submit">新增渠道</Button></Form><Divider orientation="left">已建渠道</Divider>{(data.carriers ?? []).map((item: any) => <div key={item.id} style={{ marginBottom: 8 }}><Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag><b>{item.name}</b><Typography.Text type="secondary"> · {item.code} · {item._count?.suppliers ?? 0} 个连接</Typography.Text><Button type="link" size="small" onClick={() => void openCarrierDetail(item.id)}>渠道详情</Button><Button type="link" danger size="small" disabled={(item._count?.suppliers ?? 0) > 0} onClick={() => removeCarrier(item)}>删除</Button></div>)}</Card></Col>
      <Col span={16}><Card title="新增供应商连接"><Form form={supplierForm} layout="vertical" initialValues={{ driverCode: 'FEDEX_RELAY', environment: 'SANDBOX' }} onFinish={submitSupplier}><Row gutter={12}><Col span={12}><Form.Item name="carrierId" label="所属尾程渠道" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.carriers ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.name} · ${item.code}` }))} /></Form.Item></Col><Col span={12}><Form.Item name="driverCode" label="后端接口驱动" rules={[{ required: true }]}><Select options={(data.drivers ?? []).map((item: any) => ({ value: item.code, label: `${item.code} · ${item.name}` }))} /></Form.Item></Col></Row><Row gutter={12}><Col span={12}><Form.Item name="code" label="供应商连接编号" rules={[{ required: true }]}><Input placeholder="例如 UPS_OFFICIAL_PRODUCTION_01" /></Form.Item></Col><Col span={12}><Form.Item name="name" label="供应商连接名称" rules={[{ required: true }]}><Input placeholder="FedEx Relay Sandbox" /></Form.Item></Col></Row><Form.Item name="environment" label="环境" rules={[{ required: true }]}><Select options={[{ value: 'SANDBOX', label: 'Sandbox' }, { value: 'PRODUCTION', label: 'Production' }]} /></Form.Item>{selectedDriver?.businessFields?.map((field: any) => <Form.Item key={field.key} name={['businessConfig', field.key]} label={field.label} initialValue={field.defaultValue} rules={field.required ? [{ required: true }] : undefined}>{fieldControl(field)}</Form.Item>)}<Button type="primary" htmlType="submit">保存供应商连接</Button></Form></Card></Col>
    </Row>
    <Divider orientation="left">供应商连接</Divider>
    <Table rowKey="id" dataSource={data.suppliers ?? []} pagination={{ pageSize: 10 }} onRow={(item: any) => ({ onClick: () => void openDetail(item.id), style: { cursor: 'pointer' } })} columns={[
      { title: '尾程渠道', render: (_, item: any) => <><b>{item.carrier?.name}</b><br /><Typography.Text type="secondary">{item.carrier?.code}</Typography.Text></> },
      { title: '供应商连接', render: (_, item: any) => <><b>{item.code}</b><br /><Typography.Text type="secondary">{item.name}</Typography.Text></> },
      { title: '接口 / 环境', render: (_, item: any) => <Space><Tag>{item.driverCode}</Tag><Tag color={item.environment === 'PRODUCTION' ? 'green' : 'blue'}>{item.environment}</Tag></Space> },
      { title: '状态', render: (_, item: any) => <Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag> },
      { title: '引用', render: (_, item: any) => `服务 ${item._count?.services ?? 0} · 成本 ${item._count?.costVersions ?? 0} · 账单 ${item._count?.billImportBatches ?? 0}` },
    ]} />
    <Drawer width={860} open={Boolean(carrierDetail)} title={carrierDetail ? `渠道详情 · ${carrierDetail.name}` : '渠道详情'} onClose={() => setCarrierDetail(null)}>
      {carrierDetail && <>
        <Descriptions size="small" column={2} items={[
          { key: 'name', label: '尾程渠道', children: carrierDetail.name },
          { key: 'code', label: '内部编号', children: carrierDetail.code },
          { key: 'status', label: '状态', children: <Tag color={carrierDetail.enabled ? 'green' : 'default'}>{carrierDetail.enabled ? '启用' : '停用'}</Tag> },
          { key: 'supplierCount', label: '可用供应商连接', children: `${carrierDetail.suppliers?.filter((item: any) => item.enabled).length ?? 0} / ${carrierDetail.suppliers?.length ?? 0}` },
        ]} />
        <Divider orientation="left">供应商连接</Divider>
        <Table rowKey="id" size="small" pagination={false} locale={{ emptyText: '该渠道尚未创建供应商连接' }} dataSource={carrierDetail.suppliers ?? []} columns={[
          { title: '连接', render: (_: unknown, item: any) => <><b>{item.name}</b><br /><Typography.Text type="secondary">{item.code}</Typography.Text></> },
          { title: '接口 / 环境', render: (_: unknown, item: any) => <Space><Tag>{item.driverCode}</Tag><Tag color={item.environment === 'PRODUCTION' ? 'green' : 'blue'}>{item.environment}</Tag></Space> },
          { title: '状态', render: (_: unknown, item: any) => <Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag> },
          { title: '关联', render: (_: unknown, item: any) => `服务 ${item._count?.services ?? 0} · 成本 ${item._count?.costVersions ?? 0} · 账单 ${item._count?.billImportBatches ?? 0}` },
        ]} />
        <Divider orientation="left">每周燃油附加费</Divider>
        <Alert type="info" showIcon style={{ marginBottom: 16 }} message="费率按渠道统一生效" description="该渠道下全部供应商连接及服务共用同一费率。可按周填写起止日期，也可预先维护未来周期；日期区间不能重叠。没有命中当前日期的费率时，燃油附加费为 0。" />
        <Card size="small" title="新增费率区间" style={{ marginBottom: 16 }}>
          <Form form={fuelForm} layout="vertical" onFinish={saveFuelSurcharge}>
            <Row gutter={12}>
              <Col span={8}><Form.Item name="percent" label="燃油费率" rules={[{ required: true, message: '请填写燃油费率' }, { pattern: /^\d+(\.\d{1,4})?$/, message: '最多四位小数' }]}><Input suffix="%" placeholder="例如 12.50" /></Form.Item></Col>
              <Col span={8}><Form.Item name="effectiveFrom" label="生效开始日期" rules={[{ required: true, message: '请选择开始日期' }]}><Input type="date" /></Form.Item></Col>
              <Col span={8}><Form.Item name="effectiveTo" label="生效结束日期" rules={[{ required: true, message: '请选择结束日期' }]}><Input type="date" /></Form.Item></Col>
            </Row>
            <Button type="primary" htmlType="submit">保存燃油费率</Button>
          </Form>
        </Card>
        <Table rowKey="id" size="small" pagination={false} locale={{ emptyText: '尚未设置燃油附加费' }} dataSource={carrierDetail.fuelSurcharges ?? []} columns={[
          { title: '生效开始', dataIndex: 'effectiveFrom', render: (value: string) => String(value).slice(0, 10) },
          { title: '生效结束', dataIndex: 'effectiveTo', render: (value: string) => String(value).slice(0, 10) },
          { title: '燃油费率', dataIndex: 'percent', render: (value: string) => `${value}%` },
          { title: '当前状态', render: (_: unknown, item: any) => { const now = new Date().getTime(); const start = new Date(item.effectiveFrom).getTime(); const end = new Date(item.effectiveTo).getTime(); return <Tag color={now < start ? 'blue' : now > end ? 'default' : 'green'}>{now < start ? '未生效' : now > end ? '已失效' : '生效中'}</Tag>; } },
          { title: '操作', render: (_: unknown, item: any) => <Button danger type="link" size="small" onClick={() => Modal.confirm({ title: '删除燃油费率', content: `将删除 ${String(item.effectiveFrom).slice(0, 10)} 至 ${String(item.effectiveTo).slice(0, 10)} 的 ${item.percent}% 费率。`, okText: '确认删除', okType: 'danger', onOk: () => deleteFuelSurcharge(item.id) })}>删除</Button> },
        ]} />
      </>}
    </Drawer>
    <Drawer width={860} open={Boolean(detail)} title={detail ? `供应商连接 · ${detail.name}` : '供应商连接'} onClose={() => setDetail(null)}>{detail && <><Descriptions size="small" column={2} items={[{ key: 'carrier', label: '尾程渠道', children: `${detail.carrier?.name} · ${detail.carrier?.code}` }, { key: 'driver', label: '接口驱动', children: detail.driverCode }, { key: 'environment', label: '环境', children: <Tag>{detail.environment}</Tag> }, { key: 'credentials', label: '本地凭据', children: <Tag color={detail.credentialStatus?.configured ? 'green' : 'orange'}>{detail.credentialStatus?.configured ? '已配置' : '未配置或不完整'}</Tag> }, { key: 'refs', label: '关联记录', children: `服务 ${detail.services?.length ?? 0} · 成本 ${detail.costVersions?.length ?? 0} · 账单 ${detail.billImportBatches?.length ?? 0}` }]} />{detail.driverCode === 'FEDEX_RELAY' && <Alert style={{ marginTop: 14 }} type={fedexUnifiedService ? 'success' : fedexEnabledServices.length ? 'error' : 'warning'} showIcon message={fedexUnifiedService ? '统一计价服务已就绪' : fedexEnabledServices.length ? 'FedEx 存在多个启用服务，暂不能下单' : '尚未建立 FedEx 统一计价服务'} description={fedexUnifiedService ? `“${fedexUnifiedService.name}”统一承担荷兰与泛欧的利润报价；供应商成本表覆盖各国家及邮编价格。` : fedexEnabledServices.length ? '请在服务管理中停用或整理为一个启用服务；历史订单与报价不会被修改。' : '请先在服务管理中创建一个启用的统一计价服务，再保存荷兰和泛欧国家路由。'} />}<Typography.Paragraph type="secondary" style={{ marginTop: 8 }}>{detail.credentialStatus?.missing?.join('；')}{detail.credentialStatus?.environmentMatches === false ? '；配置文件环境与供应商环境不匹配' : ''}</Typography.Paragraph><Divider /><Form layout="vertical" initialValues={{ name: detail.name, environment: detail.environment, actualDataSource: detail.actualDataSource, businessConfig: detail.businessConfig }} onFinish={saveDetail}><Form.Item name="name" label="供应商连接名称" rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="environment" label="环境" rules={[{ required: true }]}><Select options={[{ value: 'SANDBOX' }, { value: 'PRODUCTION' }]} /></Form.Item>{(data.drivers ?? []).find((item: any) => item.code === detail.driverCode)?.businessFields?.map((field: any) => <Form.Item key={field.key} name={['businessConfig', field.key]} label={field.label}>{fieldControl(field)}</Form.Item>)}<Space><Button type="primary" htmlType="submit">保存业务参数</Button><Button onClick={() => void setEnabled(!detail.enabled)}>{detail.enabled ? '停用连接' : '启用连接'}</Button><Button danger onClick={remove}>删除连接</Button></Space></Form><Divider orientation="left">国家路由</Divider><Alert type="info" showIcon style={{ marginBottom: 12 }} message="下单只选择供应商和目的国" description={detail.driverCode === 'UPS_OFFICIAL' ? '荷兰发货，Standard 国家路由覆盖已开通的荷兰及欧盟目的国。共用供应商成本表和所选服务利润。运费固定由公司寄件账号支付，不支持特殊清关区域。' : 'FedEx 共用统一计价服务；荷兰本土配置 NL，泛欧排除 NL。' } /><Space>{detail.driverCode !== 'FEDEX_RELAY' ? <Button type="primary" size="small" onClick={() => openRouteEditor({ code: 'UPS_STANDARD', name: 'Standard', routeType: 'DEFAULT', carrierServiceType: '11', customsMode: 'NONE', countryCodes: [] })}>新增 Standard 国家路由</Button> : <><Button type="primary" size="small" disabled={detail.driverCode === 'FEDEX_RELAY' && !fedexUnifiedService} onClick={() => openRouteEditor(detail.driverCode === 'FEDEX_RELAY' ? { code: 'FEDEX_NL_DOMESTIC', name: '荷兰本土', routeType: 'NL_DOMESTIC', countryCodes: ['NL'] } : undefined)}>新增荷兰本土路由</Button><Button size="small" disabled={detail.driverCode === 'FEDEX_RELAY' && !fedexUnifiedService} onClick={() => openRouteEditor(detail.driverCode === 'FEDEX_RELAY' ? { code: 'FEDEX_PAN_EUROPE', name: '泛欧经济型', routeType: 'PAN_EUROPE', countryCodes: [] } : undefined)}>新增泛欧路由</Button></>}</Space><Table style={{ marginTop: 12 }} rowKey="id" size="small" pagination={false} locale={{ emptyText: '尚未配置国家路由，不能创建新订单。' }} dataSource={detail.countryRoutes ?? []} columns={[{ title: '线路', render: (_: unknown, item: any) => <><b>{item.name}</b><br /><Typography.Text type="secondary">{item.code} · {item.routeType}</Typography.Text></> }, { title: '国家', render: (_: unknown, item: any) => (item.countries ?? []).map((country: any) => <Tag key={country.countryCode}>{country.countryCode}</Tag>) }, { title: '统一计价服务', render: (_: unknown, item: any) => item.service?.name ?? item.service?.code }, { title: '实际 serviceType', dataIndex: 'carrierServiceType' }, { title: '清关货品', dataIndex: 'customsMode', render: (value: string) => value === 'COMMODITIES' ? <Tag color="orange">需要</Tag> : <Tag>无需</Tag> }, { title: '状态', render: (_: unknown, item: any) => <Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag> }, { title: '操作', render: (_: unknown, item: any) => <Space><Button size="small" onClick={() => openRouteEditor(item)}>编辑</Button><Button size="small" danger onClick={() => removeRoute(item)}>删除</Button></Space> }]} /></>}</Drawer>
    <Modal width={720} open={Boolean(routeEditing)} destroyOnClose title={routeEditing?.id ? '编辑国家路由' : '新增国家路由'} footer={null} onCancel={() => { setRouteEditing(null); routeForm.resetFields(); }}><Form form={routeForm} layout="vertical" onFinish={saveRoute}><Row gutter={12}><Col span={12}><Form.Item name="code" label="路由编号" rules={[{ required: true }]}><Input placeholder="FEDEX_NL_DOMESTIC" /></Form.Item></Col><Col span={12}><Form.Item name="name" label="路由名称" rules={[{ required: true }]}><Input placeholder="荷兰本土" /></Form.Item></Col></Row><Row gutter={12}><Col span={8}><Form.Item name="routeType" label="路由类型" rules={[{ required: true }]}><Select options={detail?.driverCode === 'FEDEX_RELAY' ? [{ value: 'NL_DOMESTIC', label: '荷兰本土（NL）' }, { value: 'PAN_EUROPE', label: '泛欧经济型（排除 NL）' }] : [{ value: 'DEFAULT', label: 'Standard（荷兰及欧盟）' }]} /></Form.Item></Col><Col span={16}>{detail?.driverCode === 'FEDEX_RELAY' ? <Form.Item label="统一计价服务"><Input readOnly value={fedexUnifiedService ? `${fedexUnifiedService.code} · ${fedexUnifiedService.name}` : '请先确保该供应商仅有一个启用服务'} /></Form.Item> : <Form.Item name="serviceId" label="内部计价服务" rules={[{ required: true }]}><Select options={(detail?.services ?? []).filter((service: any) => service.enabled).map((service: any) => ({ value: service.id, label: `${service.code} · ${service.name}` }))} /></Form.Item>}</Col></Row><Row gutter={12}><Col span={12}><Form.Item name="countryCodes" label="适用国家" rules={[{ required: true, message: '至少选择一个国家' }]} extra={detail?.driverCode === 'FEDEX_RELAY' && editingRouteType === 'NL_DOMESTIC' ? '荷兰本土线路固定使用 NL。' : detail?.driverCode === 'UPS_OFFICIAL' ? '仅勾选 UPS 账号实际开通的荷兰及欧盟目的国。' : '泛欧线路排除 NL。'}><Select mode="multiple" disabled={detail?.driverCode === 'FEDEX_RELAY' && editingRouteType === 'NL_DOMESTIC'} showSearch options={(data.countries ?? []).filter((country: any) => country.enabled && (detail?.driverCode !== 'UPS_OFFICIAL' || (data.drivers ?? []).find((d: any) => d.code === 'UPS_OFFICIAL')?.allowedCountryCodes?.includes(country.code)) && !(detail?.driverCode === 'FEDEX_RELAY' && editingRouteType === 'PAN_EUROPE' && country.code === 'NL')).map((country: any) => ({ value: country.code, label: `${country.chineseName} · ${country.code}` }))} /></Form.Item></Col><Col span={6}>{detail?.driverCode === 'FEDEX_RELAY' ? <Form.Item label="实际 FedEx 服务"><Input readOnly value={editingRouteType === 'NL_DOMESTIC' ? 'FEDEX_PRIORITY' : editingRouteType === 'PAN_EUROPE' ? 'FEDEX_REGIONAL_ECONOMY' : '—'} /></Form.Item> : detail?.driverCode === 'UPS_OFFICIAL' ? <Form.Item label="UPS 服务"><Input readOnly value="Standard · 11" /></Form.Item> : <Form.Item name="carrierServiceType" label="实际 serviceType" rules={[{ required: true }]}><Input /></Form.Item>}</Col><Col span={6}><Form.Item name="enabled" label="状态" rules={[{ required: true }]}><Select options={[{ value: true, label: '启用' }, { value: false, label: '停用' }]} /></Form.Item></Col></Row><Alert type={detail?.driverCode === 'FEDEX_RELAY' ? 'info' : 'warning'} showIcon message={detail?.driverCode === 'FEDEX_RELAY' ? 'FedEx 底层服务、清关规则与统一计价服务会自动确定' : 'UPS Standard 固定服务代码 11'} description={detail?.driverCode === 'FEDEX_RELAY' ? editingRouteType === 'PAN_EUROPE' ? '泛欧订单会显示商品净重、原产国、HS 编码、数量、单价与币种等专属申报字段；税费固定由发件人支付，单箱最多 68 kg。' : '荷兰本土订单不要求泛欧跨境申报字段。' : '普通包裹、自备包装；运费由公司 UPS 账号支付，不生成商业发票；生产环境会创建真实运单。'} /><Space style={{ marginTop: 18 }}><Button type="primary" htmlType="submit" disabled={detail?.driverCode === 'FEDEX_RELAY' && !fedexUnifiedService}>保存国家路由</Button><Button onClick={() => setRouteEditing(null)}>取消</Button></Space></Form></Modal>
    <Modal open={Boolean(carrierToRemove)} title="删除尾程渠道" okText="确认删除" okButtonProps={{ danger: true, loading: removingCarrier }} onCancel={() => !removingCarrier && setCarrierToRemove(null)} onOk={() => void confirmRemoveCarrier()}><Typography.Paragraph>将删除“{carrierToRemove?.name} / {carrierToRemove?.code}”。</Typography.Paragraph><Typography.Paragraph type="secondary">仅没有供应商连接、成本表和账单引用时允许删除；有引用时系统会拒绝删除。</Typography.Paragraph></Modal>
  </section>;
}

function ServiceManagement({ data, request, refresh }: Context) {
  const [form] = Form.useForm();
  const supplierId = Form.useWatch('supplierId', form);
  const supplier = (data.suppliers ?? []).find((item: any) => item.id === supplierId);
  const allowedModes = Array.isArray(supplier?.businessConfig?.allowedServiceModes) ? supplier.businessConfig.allowedServiceModes : ['SINGLE_ONLY', 'MULTI_PIECE'];
  const submit = async (value: any) => {
    const allowsMultiPiece = supplier?.businessConfig?.shipmentModeHandling === 'NOT_APPLICABLE' ? true : value.allowsMultiPiece;
    try { await request('/admin/v1/products/services', { method: 'POST', body: JSON.stringify({ ...value, allowsMultiPiece }) }); message.success('服务已创建'); form.resetFields(); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  const setServiceEnabled = async (service: any, enabled: boolean) => {
    try { await request(`/admin/v1/products/services/${service.id}/enabled`, { method: 'PATCH', body: JSON.stringify({ enabled }) }); message.success(enabled ? '服务已启用' : '服务已停用'); await refresh(); }
    catch (error) { message.error(errorText(error)); }
  };
  return <section className="workspace-panel"><Typography.Title level={2}>服务管理</Typography.Title><Typography.Paragraph type="secondary">每个服务必须绑定一个已启用的供应商连接；FedEx Relay 每个连接仅可保留一个启用的统一计价服务，荷兰与泛欧共用该服务。</Typography.Paragraph><Row gutter={20}>
    <Col span={11}><Card title="新增服务"><Form form={form} layout="vertical" initialValues={{ currency: 'EUR', billingMethod: 'MAX_ACTUAL_OR_VOLUMETRIC', measurementMethod: 'PER_SHIPMENT', volumetricDivisor: '5000', minPieces: 1, chargeableWeightScale: 3, allowsMultiPiece: true }} onFinish={submit}>
      <Form.Item name="supplierId" label="绑定供应商连接" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.suppliers ?? []).filter((item: any) => item.enabled && item.carrier?.enabled).map((item: any) => ({ value: item.id, label: `${item.carrier?.name} · ${item.name} (${item.environment})` }))} /></Form.Item>
      <Row gutter={12}><Col span={12}><Form.Item name="code" label="服务代码" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={12}><Form.Item name="carrierServiceType" label="历史兼容 serviceType" extra="新订单请在供应商国家路由中填写实际 serviceType；本字段不再作为新订单的下发依据。"><Input placeholder="仅历史兼容，可留空" /></Form.Item></Col></Row>
      <Form.Item name="name" label="服务名称" rules={[{ required: true }]}><Input /></Form.Item><Row gutter={12}><Col span={8}><Form.Item name="currency" label="币种"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={8}><Form.Item name="billingMethod" label="计费方式"><Select options={[{ value: 'WEIGHT', label: '重量' }, { value: 'VOLUME', label: '体积' }, { value: 'MAX_ACTUAL_OR_VOLUMETRIC', label: '实重与材积重取大' }]} /></Form.Item></Col><Col span={8}><Form.Item name="measurementMethod" label="计重方式"><Select options={[{ value: 'PER_SHIPMENT', label: '按票' }, { value: 'PER_BOX', label: '按箱' }]} /></Form.Item></Col></Row>
      {supplier?.businessConfig?.shipmentModeHandling !== 'NOT_APPLICABLE' && <Form.Item name="allowsMultiPiece" label="一票多件" rules={[{ required: true }]}><Select options={[...(allowedModes.includes('SINGLE_ONLY') ? [{ value: false, label: '仅一件' }] : []), ...(allowedModes.includes('MULTI_PIECE') ? [{ value: true, label: '支持多件' }] : [])]} /></Form.Item>}
      <Row gutter={12}><Col span={8}><Form.Item name="volumetricDivisor" label="计抛系数"><Input /></Form.Item></Col><Col span={8}><Form.Item name="maxActualWeightKg" label="最大票实重 kg"><Input /></Form.Item></Col><Col span={8}><Form.Item name="minPieces" label="最小件数"><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col></Row><Form.Item name="chargeableWeightScale" label="收费重小数位"><InputNumber min={0} max={3} style={{ width: '100%' }} /></Form.Item><Button type="primary" htmlType="submit">保存服务</Button>
    </Form></Card></Col>
    <Col span={13}><Card title="已配置服务"><Table rowKey="id" size="small" pagination={false} dataSource={data.services} columns={[{ title: '服务', render: (_, item: any) => `${item.code} · ${item.name}` }, { title: '供应商连接', render: (_, item: any) => `${item.supplier?.carrier?.name ?? ''} · ${item.supplier?.name ?? ''}` }, { title: '环境', render: (_, item: any) => <Tag color={item.supplier?.environment === 'PRODUCTION' ? 'green' : 'blue'}>{item.supplier?.environment}</Tag> }, { title: '承运商代码', dataIndex: 'carrierServiceType' }, { title: '件数', render: (_, item: any) => item.allowsMultiPiece ? '支持多件' : '仅一件' }, { title: '币种', dataIndex: 'currency' }, { title: '状态', render: (_: unknown, item: any) => <Tag color={item.enabled ? 'green' : 'default'}>{item.enabled ? '启用' : '停用'}</Tag> }, { title: '操作', render: (_: unknown, item: any) => <Button type="link" size="small" danger={item.enabled} onClick={() => Modal.confirm({ title: item.enabled ? '停用服务' : '启用服务', content: item.enabled ? `停用“${item.name}”后，它不能用于新订单；历史订单、报价与账单保持可查。` : `启用“${item.name}”。FedEx 供应商同一时间只能有一个启用服务。`, okText: '确认', onOk: () => setServiceEnabled(item, !item.enabled) })}>{item.enabled ? '停用' : '启用'}</Button> }]} /></Card></Col>
  </Row></section>;
}

function Customers({ data, request, refresh }: Context) {
  const [selected, setSelected] = useState<any>(null); const [revealedKey, setRevealedKey] = useState(''); const [keyBusy, setKeyBusy] = useState(false);
  const open = async (customerId: string) => { try { setRevealedKey(''); setSelected(await (await request(`/admin/v1/customers/${customerId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  const issueKey = async (rotate: boolean) => {
    if (!selected) return;
    try {
      setKeyBusy(true); const response = await request(`/admin/v1/customers/${selected.id}/api-key${rotate ? '/rotate' : ''}`, { method: 'POST' }); const result = await response.json();
      setRevealedKey(result.apiKey); setSelected({ ...selected, apiKey: { keyPrefix: result.keyPrefix, createdAt: result.createdAt, rotatedAt: result.rotatedAt } }); await refresh();
      message.success(rotate ? 'API 密钥已轮换，旧密钥已失效' : 'API 密钥已创建');
    } catch (error) { message.error(errorText(error)); } finally { setKeyBusy(false); }
  };
  const copyKey = async () => { try { await navigator.clipboard.writeText(revealedKey); message.success('密钥已复制，请通过安全渠道交付客户'); } catch { message.warning('浏览器未允许复制，请手动复制下方密钥'); } };
  const saveClassification = async (value: any) => { if (!selected) return; try { const response = await request(`/admin/v1/customers/${selected.id}/classification`, { method: 'PATCH', body: JSON.stringify(value) }); setSelected(await response.json()); message.success('客户等级与分组归属已保存'); await refresh(); } catch (error) { message.error(errorText(error)); } };
  const currentLevel = (customer: any) => customer.levelAssignments?.find((item: any) => !item.effectiveTo)?.customerLevel;
  const currentGroup = (customer: any) => customer.groupAssignments?.find((item: any) => !item.effectiveTo)?.customerGroup;
  return <section className="workspace-panel"><Typography.Title level={2}>客户</Typography.Title><Row gutter={20}><Col span={9}><Card title="新增客户"><Form layout="vertical" onFinish={(value) => post(request, refresh, '/admin/v1/customers', value)}><Form.Item name="customerNo" label="客户 ID" extra="系统稳定识别编号；仅支持英文、数字、-、_、." rules={[{ required: true, message: '请填写客户 ID' }]}><Input placeholder="例如 CUS-ACME-001" /></Form.Item><Form.Item name="username" label="用户名" extra="用于页面显示，可使用中文。" rules={[{ required: true, message: '请填写用户名' }]}><Input placeholder="例如 上海某某贸易" /></Form.Item><Form.Item name="password" label="初始密码" extra="至少 10 位。" rules={[{ required: true, message: '请填写初始密码' }]}><Input.Password /></Form.Item><Form.Item name="contactName" label="联系人"><Input /></Form.Item><Form.Item name="companyName" label="公司"><Input /></Form.Item><Form.Item name="email" label="邮箱"><Input /></Form.Item><Form.Item name="phone" label="手机号"><Input /></Form.Item><Button htmlType="submit">创建客户</Button></Form></Card></Col><Col span={15}><Card title="客户列表"><Table rowKey="id" dataSource={data.customers} pagination={{ pageSize: 8 }} onRow={(record: any) => ({ onClick: () => void open(record.id), style: { cursor: 'pointer' } })} columns={[{ title: '客户 ID', dataIndex: 'customerNo' }, { title: '用户名', dataIndex: 'username' }, { title: '等级', render: (_: unknown, customer: any) => currentLevel(customer)?.name ?? '未设置' }, { title: '分组', render: (_: unknown, customer: any) => currentGroup(customer)?.name ?? '未设置' }, { title: '状态', dataIndex: 'status', render: (value) => <Tag>{value}</Tag> }, { title: 'EUR', render: (_, customer: any) => customer.wallets?.find((wallet: any) => wallet.currency === 'EUR')?.balance ?? '0.00' }, { title: 'GBP', render: (_, customer: any) => customer.wallets?.find((wallet: any) => wallet.currency === 'GBP')?.balance ?? '0.00' }]} /></Card></Col></Row>
    <Row gutter={20} style={{ marginTop: 20 }}><Col span={12}><Card title="客户等级"><Form layout="inline" onFinish={(value) => post(request, refresh, '/admin/v1/customers/levels', value)}><Form.Item name="code" rules={[{ required: true }]}><Input placeholder="编号，例如 VIP" /></Form.Item><Form.Item name="name" rules={[{ required: true }]}><Input placeholder="等级名称" /></Form.Item><Button htmlType="submit">新增等级</Button></Form><Table style={{ marginTop: 14 }} rowKey="id" size="small" pagination={false} dataSource={data.customerLevels ?? []} columns={[{ title: '编号', dataIndex: 'code' }, { title: '名称', dataIndex: 'name' }, { title: '状态', render: (_: unknown, item: any) => <Button type="link" size="small" onClick={() => void request(`/admin/v1/customers/levels/${item.id}/enabled`, { method: 'PATCH', body: JSON.stringify({ enabled: !item.enabled }) }).then(refresh)}>{item.enabled ? '启用' : '停用'}</Button> }]} /></Card></Col><Col span={12}><Card title="客户分组"><Form layout="inline" onFinish={(value) => post(request, refresh, '/admin/v1/customers/groups', value)}><Form.Item name="code" rules={[{ required: true }]}><Input placeholder="编号，例如 KEY_ACCOUNT" /></Form.Item><Form.Item name="name" rules={[{ required: true }]}><Input placeholder="分组名称" /></Form.Item><Button htmlType="submit">新增分组</Button></Form><Table style={{ marginTop: 14 }} rowKey="id" size="small" pagination={false} dataSource={data.customerGroups ?? []} columns={[{ title: '编号', dataIndex: 'code' }, { title: '名称', dataIndex: 'name' }, { title: '状态', render: (_: unknown, item: any) => <Button type="link" size="small" onClick={() => void request(`/admin/v1/customers/groups/${item.id}/enabled`, { method: 'PATCH', body: JSON.stringify({ enabled: !item.enabled }) }).then(refresh)}>{item.enabled ? '启用' : '停用'}</Button> }]} /></Card></Col></Row>
    <Modal width={760} open={Boolean(selected)} title={selected ? `客户详情 · ${selected.username}` : '客户详情'} footer={null} onCancel={() => { setSelected(null); setRevealedKey(''); }}><Space direction="vertical" size="large" style={{ width: '100%' }}>{selected && <><Descriptions size="small" column={2} items={[{ key: 'customerNo', label: '客户 ID', children: selected.customerNo }, { key: 'username', label: '用户名', children: selected.username }, { key: 'status', label: '状态', children: <Tag>{selected.status}</Tag> }, { key: 'contact', label: '联系人', children: selected.contactName || '—' }, { key: 'company', label: '公司', children: selected.companyName || '—' }, { key: 'email', label: '邮箱', children: selected.email || '—' }, { key: 'phone', label: '手机号', children: selected.phone || '—' }]} />
      <Card size="small" title="客户等级与分组"><Form layout="vertical" onFinish={saveClassification} initialValues={{ customerLevelId: currentLevel(selected)?.id, customerGroupId: currentGroup(selected)?.id, effectiveFrom: new Date().toISOString().slice(0, 10) }}><Row gutter={12}><Col span={8}><Form.Item name="customerLevelId" label="当前等级"><Select allowClear options={(data.customerLevels ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.code} · ${item.name}` }))} /></Form.Item></Col><Col span={8}><Form.Item name="customerGroupId" label="当前分组"><Select allowClear options={(data.customerGroups ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.code} · ${item.name}` }))} /></Form.Item></Col><Col span={8}><Form.Item name="effectiveFrom" label="生效日期" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col></Row><Button type="primary" htmlType="submit">保存归属</Button></Form><Row gutter={12} style={{ marginTop: 14 }}><Col span={12}><Typography.Text type="secondary">等级历史</Typography.Text><Table size="small" rowKey="id" pagination={false} dataSource={selected.levelAssignments ?? []} columns={[{ title: '等级', render: (_: unknown, item: any) => item.customerLevel?.name }, { title: '生效期', render: (_: unknown, item: any) => `${String(item.effectiveFrom).slice(0, 10)} 至 ${item.effectiveTo ? String(item.effectiveTo).slice(0, 10) : '当前'}` }]} /></Col><Col span={12}><Typography.Text type="secondary">分组历史</Typography.Text><Table size="small" rowKey="id" pagination={false} dataSource={selected.groupAssignments ?? []} columns={[{ title: '分组', render: (_: unknown, item: any) => item.customerGroup?.name }, { title: '生效期', render: (_: unknown, item: any) => `${String(item.effectiveFrom).slice(0, 10)} 至 ${item.effectiveTo ? String(item.effectiveTo).slice(0, 10) : '当前'}` }]} /></Col></Row></Card>
      <Card size="small" title="API 密钥" extra={selected.apiKey ? <Button danger loading={keyBusy} onClick={() => Modal.confirm({ title: '轮换 API 密钥', content: '轮换后旧密钥会立即失效，新的明文仅显示一次。', okText: '确认轮换', onOk: () => issueKey(true) })}>轮换密钥</Button> : <Button type="primary" loading={keyBusy} onClick={() => void issueKey(false)}>创建密钥</Button>}><Typography.Paragraph type="secondary">每个客户仅保留一个可用密钥。系统只保存哈希，客户无法在门户查看；请在本次显示后通过安全渠道交付。</Typography.Paragraph>{selected.apiKey ? <Descriptions size="small" column={2} items={[{ key: 'prefix', label: '密钥前缀', children: <Typography.Text code>{selected.apiKey.keyPrefix}</Typography.Text> }, { key: 'created', label: '创建/轮换时间', children: new Date(selected.apiKey.rotatedAt ?? selected.apiKey.createdAt).toLocaleString() }]} /> : <Alert type="info" showIcon message="尚未创建 API 密钥" />}{revealedKey && <Alert className="api-key-reveal" type="warning" showIcon message="请立即安全保存：关闭此窗口后系统无法再次显示此密钥" description={<Space direction="vertical" style={{ width: '100%' }}><Input.Password readOnly visibilityToggle value={revealedKey} /><Button onClick={() => void copyKey()}>复制密钥</Button></Space>} />}</Card>
      <Card size="small" title="余额调整"><Form layout="vertical" onFinish={(value) => { if (selected) void post(request, refresh, `/admin/v1/customers/${selected.id}/wallet-adjustments`, value); }} initialValues={{ currency: 'EUR', direction: 'CREDIT' }}><Row gutter={12}><Col span={8}><Form.Item name="currency" label="币种"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={8}><Form.Item name="direction" label="方向"><Select options={[{ value: 'CREDIT', label: '入账' }, { value: 'DEBIT', label: '扣减' }]} /></Form.Item></Col><Col span={8}><Form.Item name="amount" label="金额" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Form.Item name="reason" label="原因" rules={[{ required: true }]}><Input /></Form.Item><Button type="primary" htmlType="submit">确认调整</Button></Form></Card>
    </>}</Space></Modal></section>;
}
function CreateOrder({ data, request, refresh }: Context) { const [quote, setQuote] = useState<any>(null); const [form] = Form.useForm(); const services = data.services ?? []; const quoteOrder = async () => { try { const v = await form.validateFields(['customerId', 'serviceId', 'recipientCountryCode', 'estimatedChargeableKg']); const body = { customerId: v.customerId, serviceId: v.serviceId, countryCode: v.recipientCountryCode, chargeableWeightsKg: [v.estimatedChargeableKg] }; setQuote(await (await request('/admin/v1/pricing/quotes', { method: 'POST', body: JSON.stringify(body) })).json()); } catch (e) { message.error(errorText(e)); } }; const submit = async (v: any) => { try { const body = { ...v, idempotencyKey: crypto.randomUUID(), recipientResidential: false, boxes: [{ boxNo: 'BOX-001', weightKg: v.weightKg, lengthCm: v.lengthCm, widthCm: v.widthCm, heightCm: v.heightCm, items: [{ chineseName: v.chineseName, englishName: v.englishName, originCountryCode: v.originCountryCode, harmonizedCode: v.harmonizedCode, quantity: Number(v.quantity), unitDeclaredValue: v.unitDeclaredValue, declaredValueCurrency: v.declaredValueCurrency }] }] }; ['weightKg', 'lengthCm', 'widthCm', 'heightCm', 'chineseName', 'englishName', 'originCountryCode', 'harmonizedCode', 'quantity', 'unitDeclaredValue', 'declaredValueCurrency'].forEach((key) => delete (body as any)[key]); const result = await (await request('/admin/v1/orders', { method: 'POST', body: JSON.stringify(body) })).json(); message.success(`订单 ${result.orderNo} 已创建并预扣`); await refresh(); form.resetFields(); setQuote(null); } catch (e) { message.error(errorText(e)); } }; return <section className="workspace-panel"><Typography.Title level={2}>创建运单</Typography.Title><Alert className="status-alert" type="warning" showIcon message="选择 Sandbox 渠道服务时，创建和打印面单会调用当前 FedEx Sandbox 连接；客户、订单和预扣规则保持正式流程。" /><Form form={form} layout="vertical" initialValues={{ recipientCountryCode: 'NL', recipientCity: 'Amsterdam', recipientPostcode: '1012JS', recipientAddressLine1: 'Dam 1', recipientPhone: '+31201234567', estimatedChargeableKg: '1.000', weightKg: '1.000', lengthCm: '20', widthCm: '15', heightCm: '10', quantity: 1, unitDeclaredValue: '1.00', declaredValueCurrency: 'EUR' }} onFinish={submit}><Row gutter={16}><Col span={12}><Form.Item name="customerId" label="客户" rules={[{ required: true }]}><Select options={(data.customers ?? []).map((c: any) => ({ value: c.id, label: c.username }))} /></Form.Item></Col><Col span={12}><Form.Item name="serviceId" label="服务" rules={[{ required: true }]}><Select options={services.map((s: any) => ({ value: s.id, label: `${s.name} · ${s.channel?.environment}` }))} /></Form.Item></Col></Row><Row gutter={16}><Col span={8}><Form.Item name="recipientName" label="收件人" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="recipientPhone" label="电话" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="recipientCountryCode" label="国家" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Row gutter={16}><Col span={8}><Form.Item name="recipientPostcode" label="邮编" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="recipientCity" label="城市" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="recipientAddressLine1" label="地址" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Divider orientation="left">箱号与申报</Divider><Row gutter={12}><Col span={5}><Form.Item name="weightKg" label="实重 kg"><Input /></Form.Item></Col><Col span={5}><Form.Item name="lengthCm" label="长 cm"><Input /></Form.Item></Col><Col span={5}><Form.Item name="widthCm" label="宽 cm"><Input /></Form.Item></Col><Col span={5}><Form.Item name="heightCm" label="高 cm"><Input /></Form.Item></Col><Col span={4}><Form.Item name="estimatedChargeableKg" label="预估收费重 kg"><Input /></Form.Item></Col></Row><Row gutter={12}><Col span={7}><Form.Item name="chineseName" label="中文品名" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={7}><Form.Item name="englishName" label="英文品名" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={5}><Form.Item name="originCountryCode" label="原产国" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={5}><Form.Item name="harmonizedCode" label="HS 编码" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Row gutter={12}><Col span={6}><Form.Item name="quantity" label="数量"><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col><Col span={6}><Form.Item name="unitDeclaredValue" label="单件申报货值"><Input /></Form.Item></Col><Col span={6}><Form.Item name="declaredValueCurrency" label="申报币种"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col></Row><Space><Button onClick={quoteOrder}>试算</Button><Button type="primary" htmlType="submit">预扣并创建运单</Button></Space></Form>{quote && <Card className="quote-preview" title="试算结果"><Descriptions column={3} items={[{ key: 'cost', label: '基础成本', children: `${quote.currency} ${quote.supplierBaseFreight}` }, { key: 'profit', label: '服务利润', children: `${quote.currency} ${quote.serviceProfit}` }, { key: 'total', label: '预计应收', children: <b>{quote.currency} {quote.total}</b> }]} /></Card>}</section>; }
function OrderList({ data, request, refresh }: Context) { const [busy, setBusy] = useState(''); const run = async (orderId: string, action: 'validate' | 'create') => { setBusy(`${action}-${orderId}`); try { await request(`/admin/v1/orders/${orderId}/fedex/${action}`, { method: 'POST' }); message.success(action === 'create' ? '面单已生成' : '校验通过'); await refresh(); } catch (e) { message.error(errorText(e)); } finally { setBusy(''); } }; const print = async (order: any, label: any) => { try { previewLabel(await asLabelBlob(await request(`/admin/v1/orders/${order.id}/labels/${label.id}/inline`)), labelFilename(label)); } catch (e) { message.error(errorText(e)); } }; return <section className="workspace-panel"><Typography.Title level={2}>订单列表</Typography.Title><Table rowKey="id" dataSource={data.orders} pagination={{ pageSize: 10 }} columns={[{ title: '运单号', dataIndex: 'carrierTrackingNumber', render: (v, o: any) => v ?? o.orderNo }, { title: '客户', render: (_, o: any) => o.customer?.username }, { title: '服务', render: (_, o: any) => o.service?.name }, { title: '环境', render: (_, o: any) => <Tag color={o.service?.channel?.environment === 'PRODUCTION' ? 'green' : 'blue'}>{o.service?.channel?.environment}</Tag> }, { title: '收件国家', dataIndex: 'recipientCountryCode' }, { title: '预扣', render: (_, o: any) => `${o.currency} ${o.prechargedAmount}` }, { title: '订单状态', dataIndex: 'shipmentStatus', render: (v) => <Tag>{shipmentStatusLabel(v)}</Tag> }, { title: '操作', render: (_, o: any) => <Space><Button size="small" disabled={o.shipmentStatus !== 'SUBMITTED'} loading={busy === `validate-${o.id}`} onClick={() => run(o.id, 'validate')}>Validate</Button><Button type="primary" size="small" disabled={o.shipmentStatus !== 'SUBMITTED'} loading={busy === `create-${o.id}`} onClick={() => run(o.id, 'create')}>生成面单</Button>{o.labels?.map((label: any) => <Button size="small" key={label.id} onClick={() => print(o, label)}>{String(label.contentType ?? '').toUpperCase().includes('PDF') ? '打印 PDF' : `下载 ${label.contentType ?? '面单'}`}</Button>)}</Space> }]} /></section>; }
function CreateOrderFlow({ data, request, refresh }: Context) {
  const [quote, setQuote] = useState<any>(null);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [route, setRoute] = useState<any>(null);
  const [submissionResult, setSubmissionResult] = useState<{ title: string; type: 'success' | 'error'; detail: string; orderNo?: string } | null>(null);
  const [form] = Form.useForm();
  const supplierId = Form.useWatch('supplierId', form);
  const country = Form.useWatch('recipientCountryCode', form);
  const boxes = Form.useWatch('boxes', form) ?? [];
  const service = route?.service;
  const countryOptions = (data.countries ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.chineseName, label: `${item.chineseName} · ${item.code}` }));
  const customer = (data.customers ?? []).find((item: any) => item.id === Form.useWatch('customerId', form));
  const configuredRequired = new Set((data.declarationFields?.fields ?? []).filter((field: any) => field.required).map((field: any) => field.code));
  const driverRequired = route?.route?.fieldSchema?.declarationRequired ?? [];
  const isPanEurope = route?.route?.routeType === 'PAN_EUROPE';
  const declarationRules = (code: string, label: string) => configuredRequired.has(code) || driverRequired.includes(code) ? [{ required: true, message: `请填写${label}` }] : [];
  useEffect(() => { void (async () => { try { setSuppliers(await (await request('/admin/v1/orders/orderable-suppliers')).json()); } catch (error) { message.error(errorText(error)); } })(); }, [request]);
  useEffect(() => { if (!supplierId || !country) { setRoute(null); return; } let cancelled = false; void (async () => { try { const result = await (await request(`/admin/v1/orders/route?supplierId=${encodeURIComponent(supplierId)}&country=${encodeURIComponent(country)}`)).json(); if (!cancelled) { setRoute(result); setQuote(null); } } catch (error) { if (!cancelled) { setRoute(null); setQuote(null); message.warning(errorText(error)); } } })(); return () => { cancelled = true; }; }, [supplierId, country, request]);
  const declaredTotals = boxes.reduce((totals: Record<string, number>, box: any) => { for (const item of box.items ?? []) { const currency = item.declaredValueCurrency ?? 'EUR'; totals[currency] = (totals[currency] ?? 0) + Number(item.quantity ?? 0) * Number(item.unitDeclaredValue ?? 0); } return totals; }, {});
  const orderBody = (value: any) => {       return {
        customerId: value.customerId, supplierId: value.supplierId, idempotencyKey: crypto.randomUUID(), recipientName: value.recipientName,
        recipientCompany: value.recipientCompany || undefined, recipientPhone: value.recipientPhone, recipientCountryCode: value.recipientCountryCode,
        recipientPostcode: value.recipientPostcode, recipientCity: value.recipientCity, recipientState: value.recipientState || undefined, recipientAddress: value.recipientAddress,
        recipientResidential: Boolean(value.recipientResidential), estimatedChargeableKg: String(value.estimatedChargeableKg), taxWith: value.taxWith, taxNumber: value.taxNumber, deliveryWith: value.deliveryWith, exportWith: value.exportWith, importWith: value.importWith, shipmentAttrs: value.shipmentAttrs,
        boxes: value.boxes.map((box: any) => ({
          boxNo: box.boxNo || undefined, weightKg: String(box.weightKg), lengthCm: String(box.lengthCm), widthCm: String(box.widthCm), heightCm: String(box.heightCm),
          items: box.items.map((item: any) => ({ ...item, quantity: item.quantity === undefined || item.quantity === null || item.quantity === '' ? undefined : Number(item.quantity), unitDeclaredValue: item.unitDeclaredValue === undefined || item.unitDeclaredValue === null || item.unitDeclaredValue === '' ? undefined : String(item.unitDeclaredValue) })),
        })),
      };
 };
  const quoteOrder = async () => {
    try {
      const value = await form.validateFields();
      if (!route) throw new Error('请先选择已配置该目的国路由的供应商');
      const response = await request('/admin/v1/orders/quote', { method: 'POST', body: JSON.stringify(orderBody(value)) });
      setQuote(await response.json());
    } catch (error) { message.error(errorText(error)); }
  };
  const submit = async (value: any) => {
    try {
      const body = orderBody(value);
      const response = await request('/admin/v1/orders', { method: 'POST', body: JSON.stringify(body) });
      const order = await response.json();
      setSubmissionResult({ title: '下单成功', type: 'success', orderNo: order.orderNo, detail: '订单已完成预扣，正在自动校验并生成面单。' });
      await refresh(); form.resetFields(); setQuote(null);
    } catch (error) {
      setSubmissionResult({ title: '下单未成功', type: 'error', detail: errorText(error) });
    }
  };
  const initialValues = {
    recipientCity: '', recipientPostcode: '', recipientAddress: '', recipientPhone: '', recipientResidential: false, estimatedChargeableKg: '1.000',
    boxes: [{ weightKg: '1.000', lengthCm: '20', widthCm: '15', heightCm: '10', items: [{ chineseName: '', englishName: '', itemWeightKg: '', originCountryCode: '', harmonizedCode: '', quantity: 1, unitDeclaredValue: '1.00', declaredValueCurrency: 'EUR' }] }],
  };
  return <section className="workspace-panel">
    <Typography.Title level={2}>创建运单</Typography.Title>
    <Typography.Paragraph type="secondary">选择供应商并填写目的国后，系统会自动完成计价与承运商处理；下单人无需选择底层服务。</Typography.Paragraph>
  {route?.supplier?.environment === 'SANDBOX' && <Alert className="status-alert" type="warning" showIcon message="当前供应商为 Sandbox 连接" description="订单仍按正式预扣流程创建，但会调用 Sandbox 面单接口。" />}
  {route && <Alert className="status-alert" type="success" showIcon message="目的国已匹配，可继续填写订单" description={isPanEurope ? '请补充下方泛欧跨境申报信息后再提交。' : '当前目的国无需补充泛欧跨境申报信息。'} />}
  {isPanEurope && <Alert className="status-alert" type="warning" showIcon message="泛欧跨境申报信息" description="商品净重、英文品名、原产国、HS 编码、数量、单件货值和申报币种均为必填；单箱不超过 68 kg。下方“固定承运商规则”会随订单一并发送至 FedEx。" />}
    {service && !service.allowsMultiPiece && <Alert className="status-alert" type="info" showIcon message="当前供应商仅支持一票一件" description="订单只能保留一个箱号。" />}
    <Form form={form} layout="vertical" initialValues={initialValues} onFinish={submit}>
      <Card title="01 / 订单与收件信息" size="small">
        <Row gutter={14}>
          <Col span={8}><Form.Item name="customerId" label="客户名称" rules={[{ required: true, message: '请选择客户' }]}><Select showSearch optionFilterProp="label" options={(data.customers ?? []).map((item: any) => ({ value: item.id, label: item.username }))} /></Form.Item></Col>
          <Col span={8}><Form.Item name="supplierId" label="供应商" rules={[{ required: true, message: '请选择供应商' }]}><Select showSearch optionFilterProp="label" options={suppliers.map((item: any) => ({ value: item.id, label: `${item.carrier?.name ?? ''} · ${item.name} · ${item.environment}` }))} /></Form.Item></Col>
          <Col span={8}><Form.Item name="estimatedChargeableKg" label="预估收费重 kg" rules={[{ required: true }]}><Input /></Form.Item></Col>
        </Row>
        {customer && <div className="manifest-summary">当前客户余额：EUR {customer.wallets?.find((wallet: any) => wallet.currency === 'EUR')?.balance ?? '0.00'}　/　GBP {customer.wallets?.find((wallet: any) => wallet.currency === 'GBP')?.balance ?? '0.00'}</div>}
        <Row gutter={14} style={{ marginTop: 16 }}><Col span={6}><Form.Item name="recipientName" label="收件人" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={12}><Form.Item name="recipientAddress" label="地址" extra={`最多三行，每行 ${route?.route?.fieldSchema?.addressLineLimit ?? 20} 字符，不拆分单词`} rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={6}><Form.Item name="recipientPhone" label="电话" rules={[{ required: true }]}><Input /></Form.Item></Col></Row>
        <Row gutter={14}><Col span={5}><Form.Item name="recipientCompany" label="公司"><Input /></Form.Item></Col><Col span={4}><Form.Item name="recipientCountryCode" label="国家" rules={[{ required: true }]}><AutoComplete options={countryOptions}><Input placeholder="例如 荷兰 或 NL" /></AutoComplete></Form.Item></Col><Col span={4}><Form.Item name="recipientPostcode" label="邮编" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={4}><Form.Item name="recipientCity" label="城市" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={4}><Form.Item name="recipientState" label="省/州" rules={route?.supplier?.driverCode === 'UPS_OFFICIAL' && route?.destinationCountryCode === 'IE' ? [{ required: true, max: 5, message: 'UPS 爱尔兰需填写省/州代码（最多 5 字符）' }] : []}><Input /></Form.Item></Col><Col span={3}><Form.Item name="recipientResidential" label="住宅地址"><Select options={[{ value: false, label: '否' }, { value: true, label: '是' }]} /></Form.Item></Col></Row>
        {route?.route?.fieldSchema?.shipmentOptions?.length > 0 && <Row gutter={14}>{route.route.fieldSchema.shipmentOptions.map((field: any) => <Col span={field.code === 'shipmentAttrs' ? 12 : 6} key={field.code}><Form.Item name={field.code} label={field.label}><Select mode={field.type === 'MULTI_SELECT' ? 'multiple' : undefined} options={field.options} /></Form.Item></Col>)}</Row>}
        {isPanEurope && <Card size="small" className="cross-border-rules" title="泛欧跨境固定承运商规则" extra={<Tag color="gold">FedEx 自动下发</Tag>}>
          <Row gutter={14}>{(route?.route?.fieldSchema?.carrierRules?.fixedFields ?? []).map((field: any) => <Col span={8} key={field.code}><Form.Item label={field.label}><Select disabled value={field.value} options={[{ value: field.value, label: field.displayValue }]} /></Form.Item></Col>)}</Row>
          <Typography.Text type="secondary">当前 Ship-API Direct/FedEx 映射已确认上述固定字段。报关方式、清关方式、交税方式与 DDU/DDP 尚无本线路的已确认映射，系统不会要求填写或静默发送。</Typography.Text>
        </Card>}
      </Card>
      <Form.List name="boxes">{(boxFields, { add, remove }) => <>
        <div className="shipment-manifest__header" style={{ marginTop: 24 }}><div><span className="shipment-manifest__serial">02 / SHIPMENT MANIFEST</span><Typography.Title level={4} style={{ margin: '5px 0 0' }}>箱号与申报货品</Typography.Title></div><Button icon={<PlusOutlined />} onClick={() => { if (service && !service.allowsMultiPiece) { message.warning('当前供应商不支持一票多件'); return; } add({ weightKg: '1.000', lengthCm: '20', widthCm: '15', heightCm: '10', items: [{ chineseName: '', englishName: '', itemWeightKg: '', originCountryCode: '', harmonizedCode: '', quantity: 1, unitDeclaredValue: '1.00', declaredValueCurrency: 'EUR' }] }); }}>新增箱号</Button></div>
        {boxFields.map((box, boxIndex) => <div className="shipment-manifest" key={box.key}><div className="shipment-manifest__header"><span className="shipment-manifest__serial">BOX {String(boxIndex + 1).padStart(3, '0')}</span><Button danger type="text" icon={<DeleteOutlined />} disabled={boxFields.length === 1} onClick={() => remove(box.name)}>删除箱号</Button></div>
          <Row gutter={12}><Col span={5}><Form.Item name={[box.name, 'boxNo']} label="箱号（可选）" extra="留空后由系统生成"><Input /></Form.Item></Col><Col span={5}><Form.Item name={[box.name, 'weightKg']} label="实重 kg" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={5}><Form.Item name={[box.name, 'lengthCm']} label="长 cm" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={5}><Form.Item name={[box.name, 'widthCm']} label="宽 cm" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={4}><Form.Item name={[box.name, 'heightCm']} label="高 cm" rules={[{ required: true }]}><Input /></Form.Item></Col></Row>
          <Form.List name={[box.name, 'items']}>{(itemFields, itemActions) => <><Divider orientation="left" plain>{isPanEurope ? '泛欧跨境申报信息' : '申报明细'}</Divider>{itemFields.map((item, itemIndex) => <div className="declaration-row" key={item.key}><Row gutter={10}><Col span={4}><Form.Item name={[item.name, 'chineseName']} label="中文品名" rules={declarationRules('chineseName', '中文品名')}><Input /></Form.Item></Col><Col span={4}><Form.Item name={[item.name, 'englishName']} label="英文品名" rules={declarationRules('englishName', '英文品名')}><Input /></Form.Item></Col><Col span={4}><Form.Item name={[item.name, 'material']} label="材质" rules={declarationRules('material', '材质')}><Input /></Form.Item></Col><Col span={3}><Form.Item name={[item.name, 'originCountryCode']} label="原产国" rules={declarationRules('originCountryCode', '原产国')}><Input /></Form.Item></Col><Col span={4}><Form.Item name={[item.name, 'harmonizedCode']} label="HS 编码" rules={declarationRules('harmonizedCode', 'HS 编码')}><Input /></Form.Item></Col><Col span={2}><Form.Item name={[item.name, 'quantity']} label="数量" rules={declarationRules('quantity', '数量')}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col><Col span={3}><Form.Item name={[item.name, 'unitDeclaredValue']} label="单件货值" rules={declarationRules('unitDeclaredValue', '单件货值')}><Input /></Form.Item></Col></Row><Row gutter={10}>{isPanEurope && <Col span={4}><Form.Item name={[item.name, 'itemWeightKg']} label="商品净重 kg" rules={declarationRules('itemWeightKg', '商品净重')}><Input /></Form.Item></Col>}<Col span={4}><Form.Item name={[item.name, 'declaredValueCurrency']} label="申报币种" rules={declarationRules('declaredValueCurrency', '申报币种')}><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={4} style={{ paddingTop: 30 }}><Button type="link" danger disabled={itemFields.length === 1} onClick={() => itemActions.remove(item.name)}>删除明细 {itemIndex + 1}</Button></Col></Row></div>)}<Button type="dashed" block icon={<PlusOutlined />} onClick={() => itemActions.add({ itemWeightKg: '', quantity: 1, unitDeclaredValue: '1.00', declaredValueCurrency: 'EUR', originCountryCode: '' })}>新增申报明细</Button></>}</Form.List>
        </div>)}</>}</Form.List>
      <div className="manifest-summary">共 {boxes.length} 箱，申报总货值：{Object.entries(declaredTotals).map(([currency, amount]) => `${currency} ${Number(amount).toFixed(2)}`).join('　/　') || '未填写'}。同一运单必须保持同一申报币种。</div>
      <Space style={{ marginTop: 20 }}><Button onClick={quoteOrder}>试算</Button><Button type="primary" htmlType="submit">预扣并创建运单</Button></Space>
    </Form>
    {quote && <Card className="quote-preview" style={{ marginTop: 20 }} title="试算结果"><Descriptions column={4} items={[{ key: 'column', label: '命中价格列', children: quote.priceColumn ? `${quote.priceColumn.countryCode} · ${quote.priceColumn.postcodeRuleType === 'DEFAULT' ? '默认' : quote.priceColumn.postcodeRuleType === 'EXACT' ? quote.priceColumn.postcodeRuleStart : `${quote.priceColumn.postcodeRuleStart}-${quote.priceColumn.postcodeRuleEnd}`}` : '—' }, { key: 'weightCost', label: '重量基础成本', children: `${quote.currency} ${quote.weightFreight}` }, { key: 'minBox', label: '最低箱调整', children: `${quote.currency} ${quote.minimumPerBoxAdjustment}` }, { key: 'minShipment', label: '最低票调整', children: `${quote.currency} ${quote.minimumPerShipmentAdjustment}` }, { key: 'registration', label: '挂号费', children: `${quote.currency} ${quote.registrationFee}` }, { key: 'operation', label: '操作费', children: `${quote.currency} ${quote.operationFee}` }, { key: 'profit', label: '服务利润', children: `${quote.currency} ${quote.serviceProfit}` }, { key: 'fuel', label: '渠道燃油附加费', children: `${quote.currency} ${quote.fuelFee}` }, { key: 'total', label: '预计应收', children: <b>{quote.currency} {quote.total}</b> }]} /></Card>}
    <Modal open={Boolean(submissionResult)} title={submissionResult?.title} okText="我知道了" cancelButtonProps={{ style: { display: 'none' } }} onOk={() => setSubmissionResult(null)} onCancel={() => setSubmissionResult(null)}>
      {submissionResult && <Space direction="vertical" size={8} style={{ width: '100%' }}><Alert type={submissionResult.type} showIcon message={submissionResult.detail} />{submissionResult.orderNo && <div>订单号：<b>{submissionResult.orderNo}</b></div>}{submissionResult.type === 'success' ? <Typography.Text type="secondary">可在订单列表查看面单生成状态与失败原因。</Typography.Text> : isPanEurope && <Typography.Text type="secondary">泛欧线路请检查每条货品均已填写：商品净重、英文品名、原产国、HS 编码、数量、单件货值及申报币种；货品净重合计不能超过箱子实重。</Typography.Text>}</Space>}
    </Modal>
  </section>;
}

function OrderListManagement({ data, request, refresh }: Context) {
  const [busy, setBusy] = useState(''); const [detail, setDetail] = useState<any>(null); const [filters, setFilters] = useState<any>({}); const [dispatchUpdates, setDispatchUpdates] = useState<Record<string, any>>({}); const [preview, setPreview] = useState<{ filename: string; url?: string; error?: string; loading?: boolean } | null>(null); const [cancellingOrder, setCancellingOrder] = useState<any>(null); const [cancelError, setCancelError] = useState<string | null>(null); const previewFrameRef = useRef<HTMLIFrameElement>(null); const orderRowsRef = useRef<any[]>([]);
  const cancel = (order: any) => { setCancelError(null); setCancellingOrder(order); };
  const closePreview = () => setPreview((current) => { if (current?.url) URL.revokeObjectURL(current.url); return null; });
  const print = async (order: any, label: any) => { const filename = labelFilename(label); closePreview(); setPreview({ filename, loading: true }); try { const blob = await asLabelBlob(await request(`/admin/v1/orders/${order.id}/labels/${label.id}/inline`)); const header = new Uint8Array(await blob.slice(0, 4).arrayBuffer()); const isPdf = blob.type.toLowerCase().includes('pdf') || String.fromCharCode(...header) === '%PDF'; if (!isPdf) throw new Error('供应商返回的面单不是 PDF，无法在当前页面预览。请下载文件后核对输出格式。'); setPreview({ filename, url: URL.createObjectURL(new Blob([blob], { type: 'application/pdf' })) }); } catch (error) { setPreview({ filename, error: errorText(error) }); } };
  const printPreview = () => { const frame = previewFrameRef.current; if (!frame?.contentWindow) { message.error('PDF 尚未加载完成'); return; } frame.contentWindow.focus(); frame.contentWindow.print(); };
  const download = async (order: any, label: any) => { try { await downloadLabel(await asLabelBlob(await request(`/admin/v1/orders/${order.id}/labels/${label.id}/inline`)), labelFilename(label)); } catch (error) { message.error(errorText(error)); } };
  const openDetail = async (orderId: string) => { try { setDetail(await (await request(`/admin/v1/orders/${orderId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  const confirmCancel = async () => {
    const order = cancellingOrder;
    if (!order) return;
    setBusy(`cancel-${order.id}`);
    setCancelError(null);
    try {
      const result = await (await request(`/admin/v1/orders/${order.id}/cancel`, { method: 'POST' })).json();
      message.success(result.supplierCancelled ? '承运商已确认取消，等待会计处理退款' : '订单已取消，等待会计处理退款');
      setCancellingOrder(null);
      await refresh();
      if (detail?.id === order.id) await openDetail(order.id);
    } catch (error) {
      const reason = errorText(error);
      setCancelError(reason);
      message.error(reason);
      await refresh().catch(() => undefined);
      if (detail?.id === order.id) await openDetail(order.id);
    } finally {
      setBusy('');
    }
  };
  const orders = (data.orders ?? []).filter((order: any) => { const keyword = String(filters.keyword ?? '').trim().toLowerCase(); return (!keyword || [order.orderNo, order.carrierTrackingNumber, order.customer?.username, order.supplierRouteSnapshot?.supplierName, order.service?.name, order.recipientCountryCode].some((value) => String(value ?? '').toLowerCase().includes(keyword))) && (!filters.status || order.shipmentStatus === filters.status) && (!filters.serviceId || order.service?.id === filters.serviceId) && (!filters.customerId || order.customer?.id === filters.customerId) && (!filters.environment || order.service?.supplier?.environment === filters.environment); }).map((order: any) => ({ ...order, dispatch: dispatchUpdates[order.id] ?? order.dispatch }));
  const hasPendingDispatch = orders.some(isPendingDispatch);
  useEffect(() => { orderRowsRef.current = orders; }, [orders]);
  useEffect(() => {
    if (!hasPendingDispatch) return;
    const poll = async () => {
      if (document.hidden) return;
      const ids = orderRowsRef.current.filter(isPendingDispatch).map((order) => order.id).slice(0, 100);
      if (!ids.length) return;
      try {
        const statuses = await (await request(`/admin/v1/orders/dispatch-status?ids=${encodeURIComponent(ids.join(','))}`)).json();
        setDispatchUpdates((current) => ({ ...current, ...Object.fromEntries(statuses.map((item: any) => [item.orderId, item.dispatch])) }));
      } catch { /* 轮询失败不阻断订单列表；下一个周期继续查询。 */ }
    };
    const onVisible = () => { if (!document.hidden) void poll(); };
    void poll(); const timer = window.setInterval(() => void poll(), 5_000); document.addEventListener('visibilitychange', onVisible);
    return () => { window.clearInterval(timer); document.removeEventListener('visibilitychange', onVisible); };
  }, [hasPendingDispatch, request]);
  return <section className="workspace-panel order-list-panel"><Typography.Title level={2}>订单列表</Typography.Title><Typography.Paragraph type="secondary">点击订单查看收件信息、箱货申报、费用、面单及供应商调用记录。</Typography.Paragraph>
    <div className="order-filter"><Row gutter={12}><Col span={7}><Input value={filters.keyword} onChange={(event) => setFilters({ ...filters, keyword: event.target.value })} placeholder="订单号、运单号、客户、服务或国家" allowClear /></Col><Col span={4}><Select allowClear placeholder="订单状态" value={filters.status} onChange={(value) => setFilters({ ...filters, status: value })} style={{ width: '100%' }} options={['SUBMITTED', 'GENERATING', 'GENERATED', 'RECEIVED', 'RETURNED', 'CANCELLED', 'FAILED', 'UNKNOWN'].map((value) => ({ value, label: shipmentStatusLabel(value) }))} /></Col><Col span={4}><Select allowClear placeholder="客户" value={filters.customerId} onChange={(value) => setFilters({ ...filters, customerId: value })} style={{ width: '100%' }} options={(data.customers ?? []).map((item: any) => ({ value: item.id, label: item.username }))} /></Col><Col span={4}><Select allowClear placeholder="服务" value={filters.serviceId} onChange={(value) => setFilters({ ...filters, serviceId: value })} style={{ width: '100%' }} options={(data.services ?? []).map((item: any) => ({ value: item.id, label: item.name }))} /></Col><Col span={3}><Select allowClear placeholder="渠道环境" value={filters.environment} onChange={(value) => setFilters({ ...filters, environment: value })} style={{ width: '100%' }} options={[{ value: 'SANDBOX' }, { value: 'PRODUCTION' }]} /></Col><Col span={2}><Button onClick={() => setFilters({})}>重置</Button></Col></Row></div>
    <Table className="order-list-table" size="small" rowKey="id" dataSource={orders} scroll={{ x: 2120 }} pagination={{ pageSize: 30, showSizeChanger: true, pageSizeOptions: [30, 50, 100] }} onRow={(record: any) => ({ onClick: () => void openDetail(record.id), style: { cursor: 'pointer' } })} columns={[{ title: '运单号', dataIndex: 'orderNo', width: 180 }, { title: '转单号', dataIndex: 'carrierTrackingNumber', width: 150, render: (value) => value ?? '—' }, { title: '客户', width: 110, render: (_, order: any) => order.customer?.username }, { title: '服务', width: 150, render: (_, order: any) => order.service?.name }, { title: '尾程渠道', width: 100, render: (_, order: any) => order.service?.supplier?.carrier?.name }, { title: '环境', width: 95, render: (_, order: any) => <Tag color={order.service?.supplier?.environment === 'PRODUCTION' ? 'green' : 'blue'}>{order.service?.supplier?.environment}</Tag> }, { title: '收件国家', width: 90, dataIndex: 'recipientCountryCode' }, { title: '预扣', width: 105, render: (_, order: any) => `${order.currency} ${order.prechargedAmount}` }, { title: '订单状态', width: 125, dataIndex: 'shipmentStatus', render: (value) => <Tag>{shipmentStatusLabel(value)}</Tag> }, { title: '面单生成状态', width: 145, render: (_, order: any) => <Tag color={order.dispatch?.status === 'READY' ? 'green' : ['FAILED', 'UNKNOWN', 'STALLED', 'BLOCKED'].includes(order.dispatch?.status) ? 'red' : 'processing'}>{dispatchStatusLabel(order.dispatch?.status)}</Tag> }, { title: '生成说明', width: 275, render: (_, order: any) => order.dispatch?.message ?? '订单已受理，等待面单生成' }, { title: '费用状态', width: 145, dataIndex: 'feeStatus', render: (value) => <Tag>{feeStatusLabel(value)}</Tag> }, { title: '操作', width: 230, fixed: 'right', render: (_, order: any) => <Space onClick={(event) => event.stopPropagation()}>{order.connectorCapabilities?.cancel && <Button danger size="small" disabled={!['SUBMITTED', 'FAILED', 'GENERATED'].includes(order.shipmentStatus)} loading={busy === `cancel-${order.id}`} onClick={() => cancel(order)}>取消运单</Button>}{order.labels?.map((label: any) => <Space.Compact key={label.id}><Button size="small" onClick={() => void print(order, label)}>预览/打印 PDF</Button><Button size="small" onClick={() => void download(order, label)}>下载 PDF</Button></Space.Compact>)}</Space> }]} />
    <OrderDetailsDrawer detail={detail} onClose={() => setDetail(null)} onPrint={print} onDownload={download} onCancel={async (order) => cancel(order)} />
    <Modal open={Boolean(preview)} title={`面单预览${preview?.filename ? ` · ${preview.filename}` : ''}`} width="min(1120px, calc(100vw - 48px))" style={{ top: 24 }} destroyOnClose onCancel={closePreview} footer={<Space><Button onClick={closePreview}>关闭</Button><Button type="primary" disabled={!preview?.url} onClick={printPreview}>打印 PDF</Button></Space>}>
      {preview?.loading && <div style={{ height: 640, display: 'grid', placeItems: 'center' }}><Spin tip="正在加载 PDF 面单…" /></div>}
      {preview?.error && <Alert type="error" showIcon message="面单无法预览" description={preview.error} />}
      {preview?.url && <iframe ref={previewFrameRef} title="面单 PDF 预览" src={preview.url} style={{ display: 'block', width: '100%', height: '72vh', minHeight: 560, border: 0, background: '#525659' }} />}
    </Modal>
    <Modal open={Boolean(cancellingOrder)} title="取消运单" okText="确认取消" cancelText="暂不取消" okButtonProps={{ danger: true }} confirmLoading={busy === `cancel-${cancellingOrder?.id}`} maskClosable={!busy.startsWith('cancel-')} keyboard={!busy.startsWith('cancel-')} onOk={() => void confirmCancel()} onCancel={() => { if (!busy.startsWith('cancel-')) { setCancelError(null); setCancellingOrder(null); } }}>
      <Space direction="vertical">
        <Typography.Text>{cancellingOrder?.shipmentStatus === 'GENERATED' ? `将向 ${cancellingOrder?.service?.supplier?.carrier?.name ?? '承运商'} 取消整票转单号 ${cancellingOrder.carrierTrackingNumber ?? '—'}。仅可取消尚未交运或收货的运单。` : '该订单尚未获得有效承运商面单，将仅取消系统订单。'}</Typography.Text>
        <Typography.Text type="secondary">取消成功不会自动退款；预扣金额仍需在订单对账中由会计确认后处理。</Typography.Text>
        {cancelError && <Alert type="error" showIcon message="承运商取消未确认" description={cancelError} />}
      </Space>
    </Modal>
  </section>;
}

function OrderDetailsDrawer({ detail, onClose, onPrint, onDownload, onCancel }: { detail: any; onClose: () => void; onPrint: (order: any, label: any) => Promise<void>; onDownload: (order: any, label: any) => Promise<void>; onCancel: (order: any) => void }) {
  return <Drawer open={Boolean(detail)} width={760} title={detail ? `订单详情 · ${detail.carrierTrackingNumber ?? detail.orderNo}` : '订单详情'} onClose={onClose}>{detail && <Space direction="vertical" size="large" style={{ width: '100%' }}>
    <Card size="small" title="重要信息"><Descriptions column={2} size="small" items={[{ key: 'orderNo', label: '系统订单号', children: detail.orderNo }, { key: 'transferNo', label: '转单号', children: detail.carrierTrackingNumber ?? '待生成' }, { key: 'service', label: '服务', children: detail.service?.name }, { key: 'country', label: '目的国家', children: detail.recipientCountryCode }, { key: 'shipment', label: '订单状态', children: <Tag>{shipmentStatusLabel(detail.shipmentStatus)}</Tag> }, { key: 'dispatch', label: '面单生成状态', children: <Tag color={detail.dispatch?.status === 'READY' ? 'green' : ['FAILED', 'UNKNOWN', 'STALLED', 'BLOCKED'].includes(detail.dispatch?.status) ? 'red' : 'processing'}>{dispatchStatusLabel(detail.dispatch?.status)}</Tag> }, { key: 'dispatchMessage', label: '生成说明', children: detail.dispatch?.message ?? '—' }, { key: 'fee', label: '费用状态', children: <Tag>{feeStatusLabel(detail.feeStatus)}</Tag> }, { key: 'amount', label: '预扣金额', children: `${detail.currency} ${detail.prechargedAmount}` }]} /></Card>
    <Card size="small" title="收件人与渠道"><Descriptions column={1} size="small" items={[{ key: 'recipient', label: '收件人', children: `${detail.recipientName}${detail.recipientCompany ? ` · ${detail.recipientCompany}` : ''}` }, { key: 'address', label: '地址', children: `${detail.recipientAddressRaw ?? detail.recipientAddressLine1 ?? '—'}, ${detail.recipientPostcode} ${detail.recipientCity}${detail.recipientState ? ` ${detail.recipientState}` : ''}, ${detail.recipientCountryCode}` }, { key: 'phone', label: '电话', children: detail.recipientPhone }, { key: 'channel', label: '渠道 / 供应商连接', children: `${detail.service?.supplier?.carrier?.name ?? ''} · ${detail.service?.supplier?.name ?? ''} · ${detail.service?.supplier?.environment ?? ''}` }]} /></Card>
    <Card size="small" title={`箱货数据（${detail.boxes?.length ?? 0} 箱）`}><Table size="small" rowKey="id" pagination={false} dataSource={detail.boxes} expandable={{ expandedRowRender: (box: any) => <Table size="small" rowKey="id" pagination={false} dataSource={box.items} columns={[{ title: '中文品名', dataIndex: 'chineseName', render: (value) => value ?? '—' }, { title: '英文品名', dataIndex: 'englishName', render: (value) => value ?? '—' }, { title: '材质', dataIndex: 'material', render: (value) => value ?? '—' }, { title: '原产国', dataIndex: 'originCountryCode', render: (value) => value ?? '—' }, { title: 'HS 编码', dataIndex: 'harmonizedCode', render: (value) => value ?? '—' }, { title: '数量', dataIndex: 'quantity', render: (value) => value ?? '—' }, { title: '单价', dataIndex: 'unitDeclaredValue', render: (value) => value ?? '—' }, { title: '币种', dataIndex: 'declaredValueCurrency', render: (value) => value ?? '—' }]} /> }} columns={[{ title: '箱号', dataIndex: 'boxNo' }, { title: '箱运单号', dataIndex: 'carrierTrackingNumber', render: (value) => value ?? '—' }, { title: '实重 kg', dataIndex: 'weightKg' }, { title: '尺寸 cm', render: (_, box: any) => `${box.lengthCm} × ${box.widthCm} × ${box.heightCm}` }]} /></Card>
    <Card size="small" title="应收费用"><Table size="small" rowKey="id" pagination={false} dataSource={detail.feeLines} columns={[{ title: '费用项', dataIndex: 'feeType' }, { title: '金额', dataIndex: 'amount' }, { title: '币种', dataIndex: 'currency' }]} /></Card>
    <Card size="small" title="面单与供应商调用"><Space direction="vertical" style={{ width: '100%' }}>{detail.labels?.length ? detail.labels.map((label: any) => <Space.Compact key={label.id}><Button onClick={() => void onPrint(detail, label)}>预览/打印 PDF · {label.box?.boxNo ?? ''} · {label.trackingNumber ?? '面单'}</Button><Button onClick={() => void onDownload(detail, label)}>下载 PDF</Button></Space.Compact>) : <Typography.Text type="secondary">{detail.dispatch?.message ?? '尚未生成面单'}</Typography.Text>}{detail.dispatch?.technicalDetail && <Alert type="error" showIcon message="自动面单任务诊断信息" description={detail.dispatch.technicalDetail} />}{detail.connectorCapabilities?.cancel && ['SUBMITTED', 'FAILED', 'GENERATED'].includes(detail.shipmentStatus) && <><Button danger onClick={() => onCancel(detail)}>取消运单</Button><Typography.Text type="secondary">已生成面单时将由承运商确认是否可取消；取消成功后不会自动退款，需会计确认。</Typography.Text></>}<Divider /><Table size="small" rowKey="id" pagination={false} dataSource={detail.connectorCalls} columns={[{ title: '操作', dataIndex: 'operation' }, { title: '结果', dataIndex: 'status', render: (value) => <Tag>{value}</Tag> }, { title: 'HTTP', dataIndex: 'httpStatus' }, { title: '时间', dataIndex: 'createdAt', render: (value) => value ? new Date(value).toLocaleString() : '' }, { title: '异常', dataIndex: 'errorMessage' }]} /></Space></Card>
  </Space>}</Drawer>;
}

function CostTables({ data, request, refresh, open }: Context & { open: (key: string) => void }) {
  const [form] = Form.useForm(); const [countryForm] = Form.useForm(); const [createOpen, setCreateOpen] = useState(false); const [countryOpen, setCountryOpen] = useState(false);
  const save = async (value: any) => { try { const { countryCodes, ...input } = value; await request('/admin/v1/pricing/cost-tables', { method: 'POST', body: JSON.stringify({ ...input, countriesText: countryCodes.join(' ') }) }); message.success('成本表已创建，请在列表中打开详情写入价格'); form.resetFields(); setCreateOpen(false); await refresh(); } catch (error) { message.error(errorText(error)); } };
  const addCountry = async (value: any) => { try { await request('/admin/v1/pricing/countries', { method: 'POST', body: JSON.stringify(value) }); message.success('国家已加入国家表'); countryForm.resetFields(); await refresh(); } catch (error) { message.error(errorText(error)); } };
  const toggleCountry = async (country: any) => { try { await request(`/admin/v1/pricing/countries/${country.code}/enabled`, { method: 'PATCH', body: JSON.stringify({ enabled: !country.enabled }) }); await refresh(); } catch (error) { message.error(errorText(error)); } };
  const openCreate = () => { form.resetFields(); form.setFieldsValue({ currency: 'EUR', status: 'ACTIVE', minWeightKg: '0', minBoxes: 1, effectiveFrom: new Date().toISOString().slice(0, 10) }); setCreateOpen(true); };
  return <section className="workspace-panel"><Space align="center" style={{ width: '100%', justifyContent: 'space-between', marginBottom: 16 }}><div><Typography.Title level={2} style={{ margin: 0 }}>供应商成本表</Typography.Title><Typography.Text type="secondary">打开成本表后可维护价格矩阵与国家／邮编价格列。</Typography.Text></div><Space><Button onClick={() => setCountryOpen(true)}>国家表</Button><Button type="primary" onClick={openCreate}>新建成本表</Button></Space></Space>
    <Card title="已创建成本表"><Table rowKey="id" size="small" dataSource={data.costs} pagination={{ pageSize: 20, showSizeChanger: true }} locale={{ emptyText: '暂无成本表。请点击右上角“新建成本表”。' }} onRow={(item: any) => ({ onClick: () => open(`cost-table:${item.id}`), style: { cursor: 'pointer' } })} columns={[{ title: '供应商连接', render: (_, item: any) => `${item.supplier?.carrier?.name ?? ''} · ${item.supplier?.name ?? ''}` }, { title: '版本', dataIndex: 'versionNo' }, { title: '国家组', render: (_, item: any) => item.countries?.map((country: any) => <Tag key={country.countryCode}>{country.country?.chineseName ?? country.countryCode}</Tag>) }, { title: '生效期', render: (_, item: any) => `${String(item.effectiveFrom).slice(0, 10)} → ${item.effectiveTo ? String(item.effectiveTo).slice(0, 10) : '未设置'}` }, { title: '重量 / 箱数', render: (_, item: any) => `${item.minWeightKg}-${item.maxWeightKg ?? '不限'}kg / ${item.minBoxes}-${item.maxBoxes ?? '不限'}箱` }, { title: '价格列', render: (_, item: any) => `${item.rows?.length ?? 0} 列` }, { title: '重量规则', render: (_, item: any) => [...new Set((item.rows ?? []).map((row: any) => row.tiers?.length ?? 0))].join(' / ') || '—' }, { title: '状态', dataIndex: 'status', render: (value) => <Tag color={value === 'ACTIVE' ? 'green' : 'default'}>{value === 'ACTIVE' ? '正常' : '停用'}</Tag> }]} /></Card>
    <Modal open={createOpen} title="新建成本表" width={860} destroyOnClose footer={null} onCancel={() => setCreateOpen(false)}><Alert type="info" showIcon style={{ marginBottom: 16 }} message="创建表头后，再进入详情写入价格矩阵" description="国家组来自国家表中的启用国家；价格、邮编规则和最低费用在成本表详情中维护。" /><Form form={form} layout="vertical" onFinish={save}><Row gutter={12}><Col span={12}><Form.Item name="supplierId" label="供应商连接" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.suppliers ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.carrier?.name ?? ''} · ${item.name}` }))} /></Form.Item></Col><Col span={12}><Form.Item name="versionNo" label="版本号" rules={[{ required: true }]}><Input placeholder="FEDEX-SBX-002" /></Form.Item></Col></Row><Form.Item name="countryCodes" label="国家组" rules={[{ required: true }]} extra="仅可选择国家表中启用的国家"><Select mode="multiple" showSearch optionFilterProp="label" placeholder="选择可适用的目的国" options={(data.countries ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.code, label: `${item.chineseName} · ${item.code}` }))} /></Form.Item><Row gutter={12}><Col span={6}><Form.Item name="minWeightKg" label="最小重量 kg" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={6}><Form.Item name="maxWeightKg" label="最大重量 kg"><Input placeholder="留空表示不限" /></Form.Item></Col><Col span={6}><Form.Item name="minBoxes" label="最小箱数" rules={[{ required: true }]}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col><Col span={6}><Form.Item name="maxBoxes" label="最大箱数"><InputNumber min={1} style={{ width: '100%' }} placeholder="留空表示不限" /></Form.Item></Col></Row><Row gutter={12}><Col span={8}><Form.Item name="currency" label="币种"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={8}><Form.Item name="status" label="状态"><Select options={[{ value: 'ACTIVE', label: '正常' }, { value: 'DISABLED', label: '停用' }]} /></Form.Item></Col><Col span={8}><Form.Item label="计价方式"><Input value="混合计价（详情设置）" disabled /></Form.Item></Col></Row><Row gutter={12}><Col span={12}><Form.Item name="effectiveFrom" label="生效开始" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col><Col span={12}><Form.Item name="effectiveTo" label="生效结束" rules={[{ required: true, message: '请选择生效结束时间' }]}><Input type="date" /></Form.Item></Col></Row><Space style={{ display: 'flex', justifyContent: 'flex-end' }}><Button onClick={() => setCreateOpen(false)}>取消</Button><Button type="primary" htmlType="submit">创建成本表</Button></Space></Form></Modal>
    <Modal open={countryOpen} title="国家表" width={760} destroyOnClose footer={null} onCancel={() => setCountryOpen(false)}><Form form={countryForm} layout="vertical" onFinish={addCountry}><Row gutter={12} align="bottom"><Col span={7}><Form.Item name="code" label="二字代码" rules={[{ required: true }]}><Input maxLength={2} placeholder="BE" /></Form.Item></Col><Col span={11}><Form.Item name="chineseName" label="中文国家名" rules={[{ required: true }]}><Input placeholder="比利时" /></Form.Item></Col><Col span={6}><Form.Item label=" "><Button block type="primary" htmlType="submit">添加国家</Button></Form.Item></Col></Row></Form><Divider /><Table rowKey="code" size="small" pagination={{ pageSize: 10 }} dataSource={data.countries} columns={[{ title: '代码', dataIndex: 'code' }, { title: '国家', dataIndex: 'chineseName' }, { title: '状态', render: (_, item: any) => <Button size="small" onClick={() => void toggleCountry(item)}>{item.enabled ? '停用' : '启用'}</Button> }]} /></Modal>
  </section>;
}

function CostTableDetail({ tableId, data, request, refresh }: Context & { tableId: string }) {
  const [table, setTable] = useState<any>(null); const [pastedText, setPastedText] = useState(''); const [preview, setPreview] = useState<any>(null); const [busy, setBusy] = useState(false); const [headerBusy, setHeaderBusy] = useState(false); const [headerForm] = Form.useForm(); const [matrixEditing, setMatrixEditing] = useState(false); const [matrixDraft, setMatrixDraft] = useState<string[][]>([]);
  const load = useCallback(async () => { try { setTable(await (await request(`/admin/v1/pricing/cost-tables/${tableId}`)).json()); } catch (error) { message.error(errorText(error)); } }, [request, tableId]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (table) headerForm.setFieldsValue({ supplierId: table.supplierConnectionId, versionNo: table.versionNo, countryCodes: table.countries.map((item: any) => item.countryCode), currency: table.currency, status: table.status, effectiveFrom: table.effectiveFrom ? new Date(table.effectiveFrom).toISOString().slice(0, 10) : undefined, effectiveTo: table.effectiveTo ? new Date(table.effectiveTo).toISOString().slice(0, 10) : undefined, minWeightKg: String(table.minWeightKg), maxWeightKg: table.maxWeightKg == null ? undefined : String(table.maxWeightKg), minBoxes: table.minBoxes, maxBoxes: table.maxBoxes ?? undefined }); }, [headerForm, table]);
  const downloadTemplate = async () => { try { const response = await request(`/admin/v1/pricing/cost-tables/${tableId}/template`); const blobUrl = URL.createObjectURL(await response.blob()); const anchor = document.createElement('a'); anchor.href = blobUrl; anchor.download = `${table?.versionNo ?? '成本表'}-空白成本价格模板.xlsx`; anchor.click(); URL.revokeObjectURL(blobUrl); } catch (error) { message.error(errorText(error)); } };
  const downloadCurrentMatrix = async () => { try { const response = await request(`/admin/v1/pricing/cost-tables/${tableId}/matrix-export`); const blobUrl = URL.createObjectURL(await response.blob()); const anchor = document.createElement('a'); anchor.href = blobUrl; anchor.download = `${table?.versionNo ?? '成本表'}-当前成本价格表.xlsx`; anchor.click(); URL.revokeObjectURL(blobUrl); } catch (error) { message.error(errorText(error)); } };
  const saveHeader = async (value: any) => { try { setHeaderBusy(true); const { countryCodes, ...input } = value; const updated = await (await request(`/admin/v1/pricing/cost-tables/${tableId}`, { method: 'PATCH', body: JSON.stringify({ ...input, countriesText: countryCodes.join(' ') }) })).json(); setTable(updated); setPreview(null); setPastedText(''); await refresh(); if (updated.priceMatrixCleared) message.warning('国家组已变更，原价格矩阵已清空，请重新粘贴并写入价格'); else message.success('成本表表头已保存'); } catch (error) { message.error(errorText(error)); } finally { setHeaderBusy(false); } };
  const parse = async (text = pastedText) => { try { setBusy(true); setPreview(await (await request(`/admin/v1/pricing/cost-tables/${tableId}/price-grid/preview`, { method: 'POST', body: JSON.stringify({ pastedText: text }) })).json()); message.success('解析成功，请核对预览后写入'); } catch (error) { setPreview(null); message.error(errorText(error)); } finally { setBusy(false); } };
  const write = async () => { try { setBusy(true); const updated = await (await request(`/admin/v1/pricing/cost-tables/${tableId}/price-grid/replace`, { method: 'POST', body: JSON.stringify({ pastedText }) })).json(); setTable(updated); setPreview(null); message.success('价格矩阵已整表写入'); await refresh(); } catch (error) { message.error(errorText(error)); } finally { setBusy(false); } };
  const matrixColumns = (table?.rows ?? []).map((row: any, index: number) => ({ ...row, key: `${row.id}-${index}`, chineseName: table.countries?.find((country: any) => country.countryCode === row.countryCode)?.country?.chineseName }));
  const billingUnitLabel: Record<string, string> = { PER_SHIPMENT: '按票', PER_BOX: '按箱', PER_KG: '每KG' };
  const tierRows = [...new Map(matrixColumns.flatMap((column: any) => (column.tiers ?? []).map((tier: any) => [`${tier.minKg}|${tier.maxKg}|${tier.billingUnit}`, tier]))).entries()].map(([key, tier]) => ({ key: `tier-${key}`, label: `${(tier as any).minKg}-${Number((tier as any).maxKg) >= 999999 ? '不限' : (tier as any).maxKg}`, billingUnit: billingUnitLabel[(tier as any).billingUnit] ?? (tier as any).billingUnit, values: matrixColumns.map((column: any) => column.tiers?.find((item: any) => `${item.minKg}|${item.maxKg}|${item.billingUnit}` === key)?.fixedAmount ?? '—') }));
  const postcodeText = (column: any) => column.postcodeRuleType === 'DEFAULT' ? '' : column.postcodeRuleType === 'EXACT' ? column.postcodeRuleStart : `${column.postcodeRuleStart}-${column.postcodeRuleEnd}`;
  const matrixRows = [...tierRows, { key: 'postcode', label: '邮编开头', billingUnit: '', values: matrixColumns.map(postcodeText) }, { key: 'minimum-shipment', label: '最低票运费', billingUnit: '', values: matrixColumns.map((column: any) => column.minimumPerShipment) }, { key: 'minimum-box', label: '最低箱运费', billingUnit: '', values: matrixColumns.map((column: any) => column.minimumPerBox) }, { key: 'registration', label: '挂号费', billingUnit: '', values: matrixColumns.map((column: any) => `${column.registrationFee}/票`) }, { key: 'operation', label: '操作费', billingUnit: '', values: matrixColumns.map((column: any) => `${column.operationFeePerKg}/KG`) }];
  const countryColumnLabel = (column: any) => {
    const name = column.chineseName ?? column.countryCode;
    if (matrixColumns.filter((item: any) => item.countryCode === column.countryCode).length < 2) return name;
    return `${name}（${postcodeText(column) || '默认'}）`;
  };
  const currentMatrixDraft = () => [['重量段', '计价单位', ...matrixColumns.map((column: any) => column.chineseName ?? column.countryCode)], ...matrixRows.map((row: any) => [row.label, row.billingUnit, ...row.values.map((value: any) => String(value ?? ''))])];
  const openMatrixEditor = () => {
    if (!matrixColumns.length) { message.warning('当前成本表尚未写入价格矩阵，请先使用空白模板导入价格'); return; }
    setMatrixDraft(currentMatrixDraft()); setMatrixEditing(true);
  };
  const updateMatrixCell = (rowIndex: number, columnIndex: number, value: string) => setMatrixDraft((current) => current.map((row, currentRow) => currentRow === rowIndex ? row.map((cell, currentColumn) => currentColumn === columnIndex ? value : cell) : row));
  const previewOnlineMatrix = async () => { const text = matrixDraft.map((row) => row.join('\t')).join('\n'); setPastedText(text); setMatrixEditing(false); await parse(text); };
  return <section className="workspace-panel"><Typography.Title level={2}>成本表详情</Typography.Title>{!table ? <Spin /> : <><Typography.Paragraph type="secondary">直接修改下方内容后，点击“保存全部修改”统一保存。最低票、最低箱、挂号和操作费均由每个国家／邮编价格列在矩阵中维护。</Typography.Paragraph><Alert type="warning" showIcon style={{ marginBottom: 14 }} message="国家组变更会清空当前价格矩阵" description="国家组从供应商成本表的国家表多选。国家可在矩阵表头重复出现；重复国家须通过不同邮编规则区分。修改国家组后请重新写入价格。" /><Form form={headerForm} onFinish={saveHeader}><Descriptions bordered size="small" column={3} items={[{ key: 'supplier', label: '供应商连接', children: <Form.Item noStyle name="supplierId" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.suppliers ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.carrier?.name ?? ''} · ${item.name}` }))} /></Form.Item> }, { key: 'version', label: '版本号', children: <Form.Item noStyle name="versionNo" rules={[{ required: true }]}><Input /></Form.Item> }, { key: 'currency', label: '币种', children: <Form.Item noStyle name="currency"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item> }, { key: 'countries', label: '国家组', span: 3, children: <Form.Item noStyle name="countryCodes" rules={[{ required: true }]}><Select mode="multiple" showSearch optionFilterProp="label" placeholder="从国家表选择目的国" options={(data.countries ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.code, label: `${item.chineseName} · ${item.code}` }))} /></Form.Item> }, { key: 'minWeight', label: '最小重量 kg', children: <Form.Item noStyle name="minWeightKg" rules={[{ required: true }]}><Input /></Form.Item> }, { key: 'maxWeight', label: '最大重量 kg', children: <Form.Item noStyle name="maxWeightKg"><Input placeholder="留空表示不限" /></Form.Item> }, { key: 'minBoxes', label: '最小箱数', children: <Form.Item noStyle name="minBoxes" rules={[{ required: true }]}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item> }, { key: 'maxBoxes', label: '最大箱数', children: <Form.Item noStyle name="maxBoxes"><InputNumber min={1} style={{ width: '100%' }} placeholder="留空表示不限" /></Form.Item> }, { key: 'status', label: '状态', children: <Form.Item noStyle name="status"><Select options={[{ value: 'ACTIVE', label: '正常' }, { value: 'DISABLED', label: '停用' }]} /></Form.Item> }, { key: 'effectiveFrom', label: '生效开始', children: <Form.Item noStyle name="effectiveFrom" rules={[{ required: true }]}><Input type="date" /></Form.Item> }, { key: 'effectiveTo', label: '生效结束', children: <Form.Item noStyle name="effectiveTo"><Input type="date" /></Form.Item> }, { key: 'billing', label: '计价单位', children: <Input value="混合计价" disabled /> }]} /><Space style={{ marginTop: 14 }}><Button type="primary" htmlType="submit" loading={headerBusy}>保存全部修改</Button></Space></Form>
    <Divider orientation="left">价格矩阵写入</Divider><Alert type="info" showIcon message="复制 Excel 区域后直接粘贴" description="重量行后必须依次含“邮编开头、最低票运费、最低箱运费、挂号费、操作费”。国家列可为中文名或二字代码；同国可以重复，但每列邮编规则须不同：空白为默认、75000 为完整匹配、2000-2999 为数字范围。写入会完整替换当前成本表的价格列。" /><Space wrap style={{ margin: '14px 0' }}><Button onClick={() => void downloadTemplate()}>下载空白导入模板</Button><Button disabled={!matrixColumns.length} onClick={() => void downloadCurrentMatrix()}>导出当前价格表</Button><Button disabled={!matrixColumns.length} onClick={openMatrixEditor}>在线编辑当前矩阵</Button><Button onClick={() => void parse()} disabled={!pastedText.trim()} loading={busy}>解析预览</Button><Button type="primary" danger onClick={() => void write()} disabled={!preview || busy}>确认整表写入</Button></Space><Input.TextArea rows={12} value={pastedText} onChange={(event) => { setPastedText(event.target.value); setPreview(null); }} placeholder={'重量段\t计价单位\t法国\t法国\t荷兰\n0-1\t按票\t5.20\t5.50\t4.54\n71.01+\t每KG\t0.31\t0.35\t0.19\n邮编开头\t\t\t75000\t\n最低票运费\t\t0\t0\t0\n最低箱运费\t\t4.24\t4.50\t4.28\n挂号费\t\t0.00/票\t0.00/票\t0.00/票\n操作费\t\t0.00/KG\t0.00/KG\t0.00/KG'} />
    {preview && <Card size="small" style={{ marginTop: 14 }} title="解析预览"><Table rowKey={(item: any, index) => `${item.countryCode}-${item.postcodeRuleType}-${item.postcodeRuleStart}-${index}`} pagination={false} dataSource={preview.columns} columns={[{ title: '国家', dataIndex: 'countryCode' }, { title: '邮编规则', render: (_, item: any) => item.postcodeRuleType === 'DEFAULT' ? '默认' : item.postcodeRuleType === 'EXACT' ? item.postcodeRuleStart : `${item.postcodeRuleStart}-${item.postcodeRuleEnd}` }, { title: '最低票', dataIndex: 'minimumPerShipment' }, { title: '最低箱', dataIndex: 'minimumPerBox' }, { title: '挂号 / 票', dataIndex: 'registrationFee' }, { title: '操作 / KG', dataIndex: 'operationFeePerKg' }, { title: '重量段数', render: () => preview.rules?.length ?? 0 }]} /></Card>}
    <Divider orientation="left">当前已写入价格矩阵</Divider><Typography.Paragraph type="secondary">以下内容与 Excel 模板的行列结构一致；同名国家的重复列通过“邮编开头”行区分。表格可横向滚动查看全部国家列。</Typography.Paragraph><Table size="small" bordered rowKey="key" dataSource={matrixRows} pagination={false} scroll={{ x: Math.max(760, 280 + matrixColumns.length * 150) }} locale={{ emptyText: '尚未写入价格矩阵' }} columns={[{ title: '重量段 / 国家', dataIndex: 'label', fixed: 'left', width: 130 }, { title: '计价单位', dataIndex: 'billingUnit', fixed: 'left', width: 100 }, ...matrixColumns.map((column: any, index: number) => ({ title: <span>{countryColumnLabel(column)}</span>, width: 150, render: (_: unknown, row: any) => row.values[index] }))]} />
    <Modal open={matrixEditing} title="在线编辑当前价格矩阵" width="96vw" style={{ top: 20 }} destroyOnClose onCancel={() => setMatrixEditing(false)} footer={<Space><Button onClick={() => setMatrixEditing(false)}>取消</Button><Button type="primary" loading={busy} onClick={() => void previewOnlineMatrix()}>解析在线修改</Button></Space>}><Typography.Paragraph type="secondary">可直接修改重量段、计价单位、国家价格、邮编规则及四项附加费用。点击“解析在线修改”后，系统仍会进行完整校验；通过后再点击页面中的“确认整表写入”才会提交数据库。</Typography.Paragraph>{matrixDraft.length > 0 && <Table size="small" bordered rowKey="key" dataSource={matrixDraft.slice(1).map((row, index) => ({ key: `edit-${index}`, rowIndex: index + 1, values: row }))} pagination={false} scroll={{ x: Math.max(900, matrixDraft[0].length * 150) }} columns={matrixDraft[0].map((title, columnIndex) => ({ title, width: columnIndex < 2 ? 130 : 150, fixed: columnIndex < 2 ? 'left' as const : undefined, render: (_: unknown, row: any) => <Input size="small" value={row.values[columnIndex] ?? ''} onChange={(event) => updateMatrixCell(row.rowIndex, columnIndex, event.target.value)} /> }))} />}</Modal>
  </>}</section>;
}
function ProfitTables({ data, open }: Context & { open: (key: string) => void }) {
  return <section className="workspace-panel"><Typography.Title level={2}>服务利润表</Typography.Title><Typography.Paragraph type="secondary">按服务维护多个利润版本。报价依次匹配指定客户、客户分组、客户等级和默认报价；命中更高范围但未配置目的国时会阻止下单。</Typography.Paragraph><Alert className="status-alert" type="info" showIcon message="以服务详情维护报价" description="每个服务可设置不同有效期、适用对象和多个目的国利润规则。利润版本修改会保留审计记录，历史订单继续保留当时的利润快照。" /><Table rowKey="id" dataSource={data.profitServices ?? []} pagination={{ pageSize: 15 }} locale={{ emptyText: '尚未创建服务' }} columns={[
    { title: '服务', render: (_: unknown, service: any) => <><b>{service.code} · {service.name}</b><br /><Typography.Text type="secondary">{service.supplier?.carrier?.name} · {service.supplier?.name}</Typography.Text></> },
    { title: '环境', render: (_: unknown, service: any) => <Tag color={service.supplier?.environment === 'PRODUCTION' ? 'green' : 'blue'}>{service.supplier?.environment}</Tag> },
    { title: '利润版本', render: (_: unknown, service: any) => service._count?.profitVersions ?? 0 },
    { title: '状态', render: (_: unknown, service: any) => <Tag color={service.enabled ? 'green' : 'default'}>{service.enabled ? '启用' : '停用'}</Tag> },
    { title: '操作', render: (_: unknown, service: any) => <Button type="primary" size="small" onClick={() => open(`profit-service:${service.id}`)}>服务详情</Button> },
  ]} /></section>;
}

function ProfitServiceDetail({ data, request, refresh, serviceId }: Context & { serviceId: string }) {
  const [detail, setDetail] = useState<any>(null); const [editing, setEditing] = useState<any>(null); const [modalOpen, setModalOpen] = useState(false); const [form] = Form.useForm();
  const scope = Form.useWatch('scope', form);
  const sourceCostVersionId = Form.useWatch('sourceCostVersionId', form);
  const load = async () => { try { setDetail(await (await request(`/admin/v1/pricing/profit-services/${serviceId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  useEffect(() => { void load(); }, [serviceId]);
  const scopeLabel = (value: string) => ({ DEFAULT: '默认报价', CUSTOMER_LEVEL: '客户等级', CUSTOMER_GROUP: '客户分组', SPECIFIC_CUSTOMER: '指定客户' }[value] ?? value);
  const targetLabel = (version: any) => version.scope === 'DEFAULT' ? '全部客户' : version.scope === 'SPECIFIC_CUSTOMER' ? ((data.customers ?? []).find((item: any) => item.id === version.scopeTargetId)?.username ?? '已删除客户') : version.scope === 'CUSTOMER_GROUP' ? ((data.customerGroups ?? []).find((item: any) => item.id === version.scopeTargetId)?.name ?? '已删除分组') : ((data.customerLevels ?? []).find((item: any) => item.id === version.scopeTargetId)?.name ?? '已删除等级');
  const openCreate = () => { setEditing(null); form.resetFields(); form.setFieldsValue({ versionNo: `PV-${new Date().toISOString().slice(0, 10)}`, scope: 'DEFAULT', sourceCostVersionId: detail?.supplier?.costVersions?.[0]?.id, defaultMode: 'FIXED_AMOUNT', defaultValue: '0.00', currency: detail?.currency ?? 'EUR', status: 'ACTIVE', effectiveFrom: new Date().toISOString().slice(0, 10), rows: [] }); setModalOpen(true); };
  const openEdit = (version: any) => { setEditing(version); form.setFieldsValue({ ...version, defaultValue: String(version.defaultValue ?? '0'), effectiveFrom: String(version.effectiveFrom).slice(0, 10), effectiveTo: version.effectiveTo ? String(version.effectiveTo).slice(0, 10) : undefined, rows: version.rows.map((row: any) => ({ ...row, value: String(row.value) })) }); setModalOpen(true); };
  const save = async (value: any) => { try { const body = { ...value, serviceId, scopeTargetId: value.scope === 'DEFAULT' ? null : value.scopeTargetId || null, rows: value.rows.map((row: any) => ({ ...row, countryCode: row.countryCode.trim().toUpperCase() })) }; await request(editing ? `/admin/v1/pricing/profit-versions/${editing.id}` : '/admin/v1/pricing/profit-versions', { method: editing ? 'PATCH' : 'POST', body: JSON.stringify(body) }); message.success(editing ? '利润版本已更新并记入审计' : '利润版本已创建'); setModalOpen(false); await refresh(); await load(); } catch (error) { message.error(errorText(error)); } };
  const setStatus = (version: any, status: string) => Modal.confirm({ title: status === 'DISABLED' ? '停用利润版本' : '启用利润版本', content: `将把版本 ${version.versionNo} 设置为${status === 'DISABLED' ? '停用' : '启用'}。`, onOk: async () => { try { await request(`/admin/v1/pricing/profit-versions/${version.id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); message.success('利润版本状态已更新'); await refresh(); await load(); } catch (error) { message.error(errorText(error)); } } });
  const downloadMatrix = async (version: any) => { try { const response = await request(`/admin/v1/pricing/profit-versions/${version.id}/matrix-export`); const url = URL.createObjectURL(await response.blob()); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${version.versionNo}-利润价格表.xlsx`; anchor.click(); URL.revokeObjectURL(url); } catch (error) { message.error(errorText(error)); } };
  const targetOptions = scope === 'SPECIFIC_CUSTOMER' ? (data.customers ?? []).map((item: any) => ({ value: item.id, label: `${item.customerNo} · ${item.username}` })) : scope === 'CUSTOMER_GROUP' ? (data.customerGroups ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.code} · ${item.name}` })) : scope === 'CUSTOMER_LEVEL' ? (data.customerLevels ?? []).filter((item: any) => item.enabled).map((item: any) => ({ value: item.id, label: `${item.code} · ${item.name}` })) : [];
  const sourceCost = detail?.supplier?.costVersions?.find((item: any) => item.id === sourceCostVersionId);
  return <section className="workspace-panel"><Typography.Title level={2}>服务利润详情</Typography.Title>{detail && <><Descriptions size="small" column={3} items={[{ key: 'service', label: '服务', children: `${detail.code} · ${detail.name}` }, { key: 'carrier', label: '渠道 / 连接', children: `${detail.supplier?.carrier?.name} · ${detail.supplier?.name}` }, { key: 'environment', label: '环境', children: <Tag>{detail.supplier?.environment}</Tag> }]} /><Divider /><Space style={{ marginBottom: 16 }}><Button type="primary" onClick={openCreate}>新增利润版本</Button><Typography.Text type="secondary">先选成本表作为矩阵来源，再设置默认利润与国家例外。已下单订单不会被自动重写。</Typography.Text></Space><Table rowKey="id" dataSource={detail.profitVersions ?? []} pagination={{ pageSize: 12 }} expandable={{ expandedRowRender: (version: any) => <Space direction="vertical" style={{ width: '100%' }}><ProfitMatrixPreview version={version} /><Divider orientation="left" plain>国家例外利润</Divider><Table rowKey="id" size="small" pagination={false} dataSource={version.rows} locale={{ emptyText: '未设置国家例外，全部使用默认利润值' }} columns={[{ title: '国家', dataIndex: 'countryCode' }, { title: '利润方式', dataIndex: 'mode', render: (value) => value === 'PERCENT_OF_COST' ? '成本百分比' : '固定加价' }, { title: '利润值', dataIndex: 'value' }]} /><Divider orientation="left" plain>修改审计（最近 {version.changeLogs?.length ?? 0} 条）</Divider><Table rowKey="id" size="small" pagination={false} locale={{ emptyText: '暂无修改记录' }} dataSource={version.changeLogs ?? []} columns={[{ title: '修改时间', dataIndex: 'createdAt', render: (value) => new Date(value).toLocaleString() }, { title: '修改前', dataIndex: 'beforeSnapshot', render: (value) => Object.keys(value ?? {}).length ? <Typography.Text ellipsis={{ tooltip: JSON.stringify(value) }}>已记录</Typography.Text> : '新建版本' }, { title: '修改后', dataIndex: 'afterSnapshot', render: (value) => <Typography.Text ellipsis={{ tooltip: JSON.stringify(value) }}>已记录</Typography.Text> }]} /></Space> }} columns={[
    { title: '版本', dataIndex: 'versionNo' }, { title: '适用范围', dataIndex: 'scope', render: scopeLabel }, { title: '适用对象', render: (_: unknown, version: any) => targetLabel(version) }, { title: '默认利润', render: (_: unknown, version: any) => `${version.defaultMode === 'PERCENT_OF_COST' ? '成本百分比' : '固定加价'} ${version.defaultValue ?? '0'}` }, { title: '币种', dataIndex: 'currency' }, { title: '生效期', render: (_: unknown, version: any) => `${String(version.effectiveFrom).slice(0, 10)} ～ ${version.effectiveTo ? String(version.effectiveTo).slice(0, 10) : '长期'}` }, { title: '状态', dataIndex: 'status', render: (value) => <Tag color={value === 'ACTIVE' ? 'green' : value === 'DISABLED' ? 'default' : 'blue'}>{value}</Tag> }, { title: '操作', render: (_: unknown, version: any) => <Space><Button size="small" onClick={() => openEdit(version)}>编辑</Button><Button size="small" disabled={!version.sourceCostVersionId} onClick={() => void downloadMatrix(version)}>导出矩阵</Button><Button size="small" danger={version.status !== 'DISABLED'} onClick={() => setStatus(version, version.status === 'DISABLED' ? 'ACTIVE' : 'DISABLED')}>{version.status === 'DISABLED' ? '启用' : '停用'}</Button></Space> },
  ]} />
  <Modal width={860} title={editing ? `编辑利润版本 · ${editing.versionNo}` : '新增利润版本'} open={modalOpen} destroyOnClose footer={null} onCancel={() => setModalOpen(false)}><Form form={form} layout="vertical" onFinish={save}><Row gutter={12}><Col span={8}><Form.Item name="versionNo" label="版本号" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="scope" label="适用范围" rules={[{ required: true }]}><Select options={[{ value: 'DEFAULT', label: '默认报价' }, { value: 'CUSTOMER_LEVEL', label: '客户等级' }, { value: 'CUSTOMER_GROUP', label: '客户分组' }, { value: 'SPECIFIC_CUSTOMER', label: '指定客户' }]} /></Form.Item></Col><Col span={8}><Form.Item name="scopeTargetId" label="适用对象" rules={scope === 'DEFAULT' ? undefined : [{ required: true, message: '请选择适用对象' }]}><Select disabled={scope === 'DEFAULT'} allowClear options={targetOptions} placeholder={scope === 'DEFAULT' ? '默认报价适用于全部客户' : '请选择'} /></Form.Item></Col></Row><Row gutter={12}><Col span={12}><Form.Item name="sourceCostVersionId" label="映射成本表" extra="用于生成同结构的利润价格矩阵；实际下单仍按计费日期匹配成本表"><Select allowClear showSearch optionFilterProp="label" options={(detail?.supplier?.costVersions ?? []).map((item: any) => ({ value: item.id, label: `${item.versionNo} · ${item.currency} · ${String(item.effectiveFrom).slice(0, 10)} 至 ${item.effectiveTo ? String(item.effectiveTo).slice(0, 10) : '长期'}` }))} /></Form.Item></Col><Col span={6}><Form.Item name="defaultMode" label="默认利润方式" rules={[{ required: true }]}><Select options={[{ value: 'FIXED_AMOUNT', label: '固定加价' }, { value: 'PERCENT_OF_COST', label: '成本百分比' }]} /></Form.Item></Col><Col span={6}><Form.Item name="defaultValue" label="默认利润值" rules={[{ required: true, pattern: /^-?\d+(\.\d{1,4})?$/, message: '最多四位小数' }]}><Input /></Form.Item></Col></Row>{sourceCost && <Alert type="info" showIcon message={`已映射成本表 ${sourceCost.versionNo}`} description={`矩阵包含 ${sourceCost.rows?.length ?? 0} 个国家/邮编价格列；未设置国家例外时，全部列使用默认利润值。`} />}<Row gutter={12} style={{ marginTop: 12 }}><Col span={6}><Form.Item name="currency" label="币种" rules={[{ required: true }]}><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={6}><Form.Item name="status" label="状态" rules={[{ required: true }]}><Select options={['DRAFT', 'SCHEDULED', 'ACTIVE', 'DISABLED'].map((value) => ({ value, label: value }))} /></Form.Item></Col><Col span={6}><Form.Item name="effectiveFrom" label="生效开始" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col><Col span={6}><Form.Item name="effectiveTo" label="生效结束"><Input type="date" /></Form.Item></Col></Row><Form.List name="rows">{(fields, actions) => <><Divider orientation="left">国家例外利润（未设置的国家走默认利润）</Divider>{fields.map((field) => <Row gutter={12} key={field.key}><Col span={7}><Form.Item name={[field.name, 'countryCode']} label="国家代码" rules={[{ required: true, pattern: /^[A-Za-z]{2}$/, message: '两位国家代码' }]}><Input maxLength={2} /></Form.Item></Col><Col span={8}><Form.Item name={[field.name, 'mode']} label="利润方式" rules={[{ required: true }]}><Select options={[{ value: 'FIXED_AMOUNT', label: '固定加价' }, { value: 'PERCENT_OF_COST', label: '成本百分比' }]} /></Form.Item></Col><Col span={7}><Form.Item name={[field.name, 'value']} label="利润值" rules={[{ required: true, pattern: /^-?\d+(\.\d{1,4})?$/, message: '最多四位小数' }]}><Input /></Form.Item></Col><Col span={2} style={{ paddingTop: 30 }}><Button danger type="text" onClick={() => actions.remove(field.name)}>删除</Button></Col></Row>)}<Button type="dashed" block onClick={() => actions.add({ countryCode: 'NL', mode: 'FIXED_AMOUNT', value: '0.00' })}>新增国家例外</Button></>}</Form.List><Space style={{ marginTop: 20 }}><Button type="primary" htmlType="submit">保存利润版本</Button><Button onClick={() => setModalOpen(false)}>取消</Button></Space></Form></Modal></>}</section>;
}
function ProfitMatrixPreview({ version }: { version: any }) {
  const cost = version.sourceCostVersion;
  if (!cost) return <Alert type="warning" showIcon message="尚未选择映射成本表" description="此版本仍可按默认利润下单，但不能生成同结构的利润价格矩阵或导出。" />;
  const columns = cost.rows ?? [];
  const unitLabel: Record<string, string> = { PER_SHIPMENT: '按票', PER_BOX: '按箱', PER_KG: '每KG' };
  const rules = [...new Map(columns.flatMap((column: any) => (column.tiers ?? []).map((tier: any) => [`${tier.minKg}|${tier.maxKg}|${tier.billingUnit}`, tier]))).entries()];
  const ruleFor = (countryCode: string) => (version.rows ?? []).find((row: any) => row.countryCode === countryCode) ?? { mode: version.defaultMode ?? 'FIXED_AMOUNT', value: version.defaultValue ?? '0' };
  const price = (amount: any, countryCode: string) => { const rule = ruleFor(countryCode); const base = Number(amount); const value = Number(rule.value); return Number.isFinite(base) && Number.isFinite(value) ? (rule.mode === 'PERCENT_OF_COST' ? base * (1 + value / 100) : base + value).toFixed(4) : '—'; };
  const displayRows = rules.map(([key, tier]: any) => ({ key, weight: `${tier.minKg}-${Number(tier.maxKg) >= 999999 ? '不限' : tier.maxKg}`, billingUnit: unitLabel[tier.billingUnit] ?? tier.billingUnit, values: columns.map((column: any) => { const matched = column.tiers?.find((item: any) => `${item.minKg}|${item.maxKg}|${item.billingUnit}` === key); return matched ? price(matched.fixedAmount, column.countryCode) : '—'; }) }));
  const countryName = (countryCode: string) => cost.countries?.find((item: any) => item.countryCode === countryCode)?.country?.chineseName ?? countryCode;
  return <Card size="small" title="映射利润价格矩阵" extra={<Tag color="blue">成本表 {cost.versionNo}</Tag>}><Typography.Paragraph type="secondary">矩阵值为“成本价格 + 利润”后的基础运费预览；挂号费、操作费、燃油及服务附加费不在此表中叠加。相同国家的不同邮编列使用相同国家例外利润。</Typography.Paragraph><Table size="small" bordered rowKey="key" dataSource={displayRows} pagination={false} scroll={{ x: Math.max(720, 230 + columns.length * 145) }} columns={[{ title: '重量段 / 国家', dataIndex: 'weight', fixed: 'left', width: 125 }, { title: '计价单位', dataIndex: 'billingUnit', fixed: 'left', width: 95 }, ...columns.map((column: any, index: number) => ({ title: `${countryName(column.countryCode)}${columns.filter((item: any) => item.countryCode === column.countryCode).length > 1 ? ` #${columns.slice(0, index + 1).filter((item: any) => item.countryCode === column.countryCode).length}` : ''}`, width: 145, render: (_: unknown, row: any) => row.values[index] }))]} /><Divider orientation="left" plain>当前利润规则</Divider><Table size="small" rowKey={(item: any) => item.countryCode} pagination={false} dataSource={[...new Map(columns.map((column: any) => [column.countryCode, column.countryCode])).values()].map((countryCode: any) => ({ countryCode, ...ruleFor(countryCode), source: (version.rows ?? []).some((row: any) => row.countryCode === countryCode) ? '国家例外' : '默认利润' }))} columns={[{ title: '国家', dataIndex: 'countryCode', render: (value) => `${countryName(value)} · ${value}` }, { title: '来源', dataIndex: 'source' }, { title: '方式', dataIndex: 'mode', render: (value) => value === 'PERCENT_OF_COST' ? '成本百分比' : '固定加价' }, { title: '利润值', dataIndex: 'value' }]} /></Card>;
}

function ExcelOrderImport({ data, request, refresh }: Context) {
  const [rows, setRows] = useState<any[]>([]); const [preview, setPreview] = useState<any[]>([]); const [sourceFileName, setSourceFileName] = useState(''); const [busy, setBusy] = useState(false);
  const downloadTemplate = () => { const headers = ['导入订单号', '客户编号', '供应商编号', '收件人', '收件公司', '收件电话', '国家', '邮编', '城市', '省/州', '地址', '是否住宅地址', '预估收费重(kg)', '箱号', '实重(kg)', '长(cm)', '宽(cm)', '高(cm)', '中文品名', '英文品名', '材质', '商品净重(kg)', '原产国', 'HS编码', '数量', '单件申报货值', '申报币种']; const sheet = XLSX.utils.json_to_sheet([{ '导入订单号': 'IMPORT-001', '客户编号': 'CUS-请替换', '供应商编号': 'SUPPLIER-请替换', '收件人': 'Jane Doe', '收件公司': '', '收件电话': '+31201234567', '国家': '荷兰', '邮编': '1012JS', '城市': 'Amsterdam', '省/州': '', '地址': 'Dam 1', '是否住宅地址': '否', '预估收费重(kg)': '1.000', '箱号': '', '实重(kg)': '1.000', '长(cm)': '20', '宽(cm)': '15', '高(cm)': '10', '中文品名': '样品', '英文品名': 'Sample', '材质': 'Plastic', '商品净重(kg)': '0.500', '原产国': 'CN', 'HS编码': '392690', '数量': 1, '单件申报货值': '1.00', '申报币种': 'EUR' }], { header: headers }); const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, '订单导入'); XLSX.writeFileXLSX(workbook, 'movix-order-import-template.xlsx'); };
  const parseFile = async (file: File) => {
    try {
      setBusy(true); const workbook = XLSX.read(await file.arrayBuffer(), { type: 'array' }); const firstSheet = workbook.Sheets[workbook.SheetNames[0]]; if (!firstSheet) throw new Error('工作簿不包含可读取的工作表');
      const records = XLSX.utils.sheet_to_json<Record<string, unknown>>(firstSheet, { defval: '' }); if (!records.length) throw new Error('工作表没有导入数据');
      const groups = new Map<string, any>(); const localErrors: any[] = [];
      const value = (record: Record<string, unknown>, key: string) => String(record[key] ?? '').trim();
      records.forEach((record, index) => { const rowNo = index + 2; const reference = value(record, '导入订单号'); const customerNo = value(record, '客户编号'); const supplierCode = value(record, '供应商编号'); const customer = (data.customers ?? []).find((item: any) => item.customerNo === customerNo); const supplier = (data.suppliers ?? []).find((item: any) => item.code === supplierCode); const boxNo = value(record, '箱号'); if (!reference || !customer || !supplier) { localErrors.push({ rowNo, status: 'ERROR', error: !reference ? '缺少导入订单号' : !customer ? `未找到客户：${customerNo || '空'}` : `未找到供应商：${supplierCode || '空'}` }); return; }
        const existing = groups.get(reference); if (existing && (existing.customerId !== customer.id || existing.order.supplierId !== supplier.id)) { localErrors.push({ rowNo, status: 'ERROR', error: '同一导入订单号的客户或供应商不一致' }); return; }
        const order = existing ?? { rowNo, customerId: customer.id, order: { supplierId: supplier.id, recipientName: value(record, '收件人'), recipientCompany: value(record, '收件公司') || undefined, recipientPhone: value(record, '收件电话'), recipientCountryCode: value(record, '国家') || value(record, '国家代码'), recipientPostcode: value(record, '邮编'), recipientCity: value(record, '城市'), recipientState: value(record, '省/州') || undefined, recipientAddress: value(record, '地址'), recipientResidential: ['是', 'Y', 'YES', 'TRUE', '1'].includes(value(record, '是否住宅地址').toUpperCase()), estimatedChargeableKg: value(record, '预估收费重(kg)'), boxes: [] } };
        let box = boxNo ? order.order.boxes.find((item: any) => item.boxNo === boxNo) : undefined; if (!box) { box = { boxNo: boxNo || undefined, weightKg: value(record, '实重(kg)'), lengthCm: value(record, '长(cm)'), widthCm: value(record, '宽(cm)'), heightCm: value(record, '高(cm)'), items: [] }; order.order.boxes.push(box); }
        const quantity = value(record, '数量');
        box.items.push({ chineseName: value(record, '中文品名') || undefined, englishName: value(record, '英文品名') || undefined, material: value(record, '材质') || undefined, itemWeightKg: value(record, '商品净重(kg)') || undefined, originCountryCode: value(record, '原产国').toUpperCase() || undefined, harmonizedCode: value(record, 'HS编码') || undefined, quantity: quantity ? Number(quantity) : undefined, unitDeclaredValue: value(record, '单件申报货值') || undefined, declaredValueCurrency: value(record, '申报币种').toUpperCase() || undefined }); groups.set(reference, order);
      });
      const parsedRows = [...groups.values()]; setRows(parsedRows); setSourceFileName(file.name); const serverPreview = parsedRows.length ? await (await request('/admin/v1/orders/import/preview', { method: 'POST', body: JSON.stringify({ sourceFileName: file.name, rows: parsedRows }) })).json() : []; setPreview([...localErrors, ...serverPreview].sort((a, b) => a.rowNo - b.rowNo)); message.success(`已解析 ${records.length} 行，聚合为 ${parsedRows.length} 票订单`);
    } catch (error) { setRows([]); setPreview([]); message.error(errorText(error)); } finally { setBusy(false); }
  };
  const commit = () => { Modal.confirm({ title: '确认批量创建订单', content: `将创建 ${rows.length} 票订单并按每票试算金额预扣客户余额。成功订单将自动进入面单校验与生成队列。`, okText: '确认创建', onOk: async () => { try { setBusy(true); const result = await (await request('/admin/v1/orders/import/commit', { method: 'POST', body: JSON.stringify({ sourceFileName, rows }) })).json(); setPreview(result); const createdCount = result.filter((item: any) => item.status === 'CREATED').length; const failedCount = result.length - createdCount; Modal.success({ title: 'Excel 下单结果', okText: '我知道了', content: <Space direction="vertical" size={4}><div>成功创建 {createdCount} 票，失败 {failedCount} 票。</div>{createdCount > 0 && <><div>成功订单已完成预扣，正在自动校验并生成面单。</div><Typography.Text type="secondary">请在订单列表查看实时生成状态与失败原因。</Typography.Text></>}</Space> }); await refresh(); } catch (error) { message.error(errorText(error)); } finally { setBusy(false); } } }); };
  const ready = rows.length > 0 && preview.length === rows.length && preview.every((item) => item.status === 'READY');
  return <section className="workspace-panel"><Typography.Title level={2}>Excel 导入</Typography.Title><Typography.Paragraph type="secondary">模板中每一行代表一条申报货品。相同“导入订单号 + 箱号”的多行会合并为同一箱；箱号留空时，每一行会作为独立箱由系统生成订单号前缀箱号。</Typography.Paragraph><Alert className="status-alert" type="info" showIcon message="导入按两步执行：先预校验，再确认创建" description="预校验会按供应商与目的国解析国家路由，并检查箱货必填项、泛欧商品净重、服务限制、报价和余额；确认后才创建订单并预扣。重复确认相同来源文件和内容时由后端幂等键保护。" /><Space><Button onClick={downloadTemplate}>下载 Excel 模板</Button><Upload accept=".xlsx,.xls" maxCount={1} showUploadList beforeUpload={(file) => { void parseFile(file); return false; }}><Button type="primary" loading={busy}>选择并解析 Excel</Button></Upload><Button disabled={!ready || busy} onClick={commit}>确认创建 {rows.length || ''} 票订单</Button></Space><Divider orientation="left">预校验/导入结果</Divider><Table rowKey="rowNo" dataSource={preview} pagination={{ pageSize: 20 }} locale={{ emptyText: '请下载模板并上传填写后的 Excel 文件' }} columns={[{ title: 'Excel 行号', dataIndex: 'rowNo' }, { title: '结果', dataIndex: 'status', render: (status) => <Tag color={status === 'READY' || status === 'CREATED' ? 'green' : 'red'}>{status}</Tag> }, { title: '预计应收', render: (_, item: any) => item.estimatedReceivable != null ? `${item.currency} ${item.estimatedReceivable}` : '—' }, { title: '创建订单', dataIndex: 'orderNo', render: (value) => value ?? '—' }, { title: '面单状态', dataIndex: 'labelStatus', render: (value) => value === 'PENDING' ? <Tag color="processing">等待面单生成</Tag> : '—' }, { title: '说明', render: (_, item: any) => item.message ?? item.error ?? '校验通过' }]} /></section>;
}

function SupplierBillsManagement({ data, request, refresh }: Context) {
  const [form] = Form.useForm(); const [busy, setBusy] = useState(''); const [detail, setDetail] = useState<any>(null);
  const supplierConnectionId = Form.useWatch('supplierConnectionId', form);
  const supplierConnection = (data.suppliers ?? []).find((item: any) => item.id === supplierConnectionId);
  const save = async (value: any) => { try { if (!supplierConnection) throw new Error('请选择供应商连接'); setBusy('create'); const body = { ...value, supplierId: supplierConnection.carrierId, channelId: supplierConnection.id, rows: value.rows.map((row: any) => ({ lineNo: Number(row.lineNo), trackingNumber: row.trackingNumber || undefined, supplierActualWeightKg: row.supplierActualWeightKg || undefined, finalChargeableWeightKg: row.finalChargeableWeightKg || undefined, supplierFinalCost: row.supplierFinalCost || undefined, currency: value.currency, rawData: { source: 'manual-standardized-entry', originalLineNo: row.lineNo } })) }; delete body.supplierConnectionId; await request('/admin/v1/billing/imports', { method: 'POST', body: JSON.stringify(body) }); message.success('账单批次已导入并完成匹配'); form.resetFields(); await refresh(); } catch (error) { message.error(errorText(error)); } finally { setBusy(''); } };
  const openDetail = async (batchId: string) => { try { setDetail(await (await request(`/admin/v1/billing/imports/${batchId}`)).json()); } catch (error) { message.error(errorText(error)); } };
  const apply = (batch: any) => { Modal.confirm({ title: '应用账单匹配结果', content: '应用后将把已匹配的实重、收费重和供应商成本写入订单，并创建待会计确认的对账记录；此操作不会立即调整客户余额。', okText: '确认应用', onOk: async () => { try { setBusy(`apply-${batch.id}`); await request(`/admin/v1/billing/imports/${batch.id}/apply`, { method: 'POST' }); message.success('匹配结果已应用，等待会计确认'); await refresh(); if (detail?.id === batch.id) await openDetail(batch.id); } catch (error) { message.error(errorText(error)); } finally { setBusy(''); } } }); };
  return <section className="workspace-panel"><Typography.Title level={2}>供应商账单导入</Typography.Title><Alert className="status-alert" type="info" showIcon message="当前录入的是标准化账单行" description="可直接填入运单号、供应商实重、最终收费重和成本，系统会自动匹配订单与渠道。真实 XLSX/CSV 文件上传将在取得供应商账单样本后接入相同的导入链路。" />
    <Card title="01 / 新建账单批次"><Form form={form} layout="vertical" initialValues={{ currency: 'EUR', originalFilename: `manual-bill-${new Date().toISOString().slice(0, 10)}.json`, rows: [{ lineNo: 1 }] }} onFinish={save}><Row gutter={12}><Col span={12}><Form.Item name="supplierConnectionId" label="供应商连接" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={(data.suppliers ?? []).map((item: any) => ({ value: item.id, label: `${item.carrier?.name ?? ''} · ${item.name} (${item.environment})` }))} /></Form.Item></Col><Col span={4}><Form.Item name="currency" label="币种"><Select options={[{ value: 'EUR' }, { value: 'GBP' }]} /></Form.Item></Col><Col span={8}><Form.Item name="originalFilename" label="来源文件名/批次名" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Row gutter={12}><Col span={6}><Form.Item name="billingPeriodFrom" label="账期开始"><Input type="date" /></Form.Item></Col><Col span={6}><Form.Item name="billingPeriodTo" label="账期结束"><Input type="date" /></Form.Item></Col></Row><Form.List name="rows">{(fields, { add, remove }) => <><div className="billing-rows-title"><span>标准化账单明细</span><Button size="small" icon={<PlusOutlined />} onClick={() => add({ lineNo: fields.length + 1 })}>新增行</Button></div>{fields.map((field) => <div className="billing-row" key={field.key}><Row gutter={10}><Col span={3}><Form.Item name={[field.name, 'lineNo']} label="行号" rules={[{ required: true }]}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col><Col span={7}><Form.Item name={[field.name, 'trackingNumber']} label="承运商运单号"><Input /></Form.Item></Col><Col span={5}><Form.Item name={[field.name, 'supplierActualWeightKg']} label="供应商实重 kg"><Input /></Form.Item></Col><Col span={5}><Form.Item name={[field.name, 'finalChargeableWeightKg']} label="最终收费重 kg"><Input /></Form.Item></Col><Col span={4}><Form.Item name={[field.name, 'supplierFinalCost']} label="供应商成本" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Button type="link" danger disabled={fields.length === 1} onClick={() => remove(field.name)}>删除此行</Button></div>)}</>}</Form.List><Button type="primary" htmlType="submit" loading={busy === 'create'}>导入并自动匹配</Button></Form></Card>
    <Divider orientation="left">已导入批次</Divider><Table rowKey="id" dataSource={data.bills} pagination={{ pageSize: 10 }} columns={[{ title: '批次', dataIndex: 'originalFilename' }, { title: '尾程渠道', render: (_, item: any) => item.supplier?.name }, { title: '供应商连接', render: (_, item: any) => item.channel?.name ?? '全部连接' }, { title: '行数', dataIndex: 'totalRows' }, { title: '匹配', render: (_, item: any) => `${item.matchedRows} / ${item.totalRows}` }, { title: '状态', dataIndex: 'status', render: (value) => <Tag>{value}</Tag> }, { title: '操作', render: (_, item: any) => <Space><Button size="small" onClick={() => void openDetail(item.id)}>查看明细</Button><Button type="primary" size="small" disabled={item.status === 'APPLIED'} loading={busy === `apply-${item.id}`} onClick={() => apply(item)}>应用匹配</Button></Space> }]} />
    <Drawer width={760} open={Boolean(detail)} title={detail ? `账单批次 · ${detail.originalFilename}` : '账单明细'} onClose={() => setDetail(null)}>{detail && <><Descriptions size="small" column={2} items={[{ key: 'supplier', label: '尾程渠道', children: detail.supplier?.name }, { key: 'channel', label: '供应商连接', children: detail.channel?.name ?? '全部连接' }, { key: 'status', label: '状态', children: <Tag>{detail.status}</Tag> }, { key: 'match', label: '匹配情况', children: `${detail.matchedRows} / ${detail.totalRows}` }]} /><Table style={{ marginTop: 20 }} rowKey="id" size="small" dataSource={detail.lines} pagination={false} columns={[{ title: '行号', dataIndex: 'lineNo' }, { title: '运单号', dataIndex: 'trackingNumber' }, { title: '系统订单', render: (_, item: any) => item.order?.carrierTrackingNumber ?? item.order?.orderNo ?? '—' }, { title: '实重', dataIndex: 'supplierActualWeightKg' }, { title: '收费重', dataIndex: 'finalChargeableWeightKg' }, { title: '成本', dataIndex: 'supplierFinalCost' }, { title: '结果', dataIndex: 'matchStatus', render: (value) => <Tag>{value}</Tag> }, { title: '说明', dataIndex: 'matchMessage' }]} /></>}</Drawer>
  </section>;
}

function ReconciliationManagement({ data, request, refresh }: Context) {
  const [selected, setSelected] = useState<any>(null);
  const [recalculating, setRecalculating] = useState<any>(null);
  const [latestResult, setLatestResult] = useState<any>(null);
  const [busy, setBusy] = useState(false);
  const confirm = async (value: any) => {
    if (!selected) return;
    try { setBusy(true); const result = await (await request(`/admin/v1/billing/reconciliations/${selected.id}/confirm`, { method: 'POST', body: JSON.stringify(value) })).json(); message.success(`对账已确认，余额差额 ${result.differenceAmount}`); setSelected(null); setLatestResult(null); await refresh(); } catch (error) { message.error(errorText(error)); } finally { setBusy(false); }
  };
  const recalculate = async (value: any) => {
    if (!recalculating) return;
    try {
      setBusy(true);
      const result = await (await request(`/admin/v1/billing/reconciliations/${recalculating.id}/recalculate`, { method: 'POST', body: JSON.stringify(value) })).json();
      setLatestResult(result); setRecalculating(null); setSelected(recalculating); message.success(`重算完成：${recalculating.currency} ${result.calculatedAmount}`); await refresh();
    } catch (error) { message.error(errorText(error)); } finally { setBusy(false); }
  };
  const recalcInitial = recalculating ? { asOfDate: String(recalculating.order?.createdAt ?? new Date().toISOString()).slice(0, 10), boxes: (recalculating.order?.boxes ?? []).map((box: any) => ({ boxId: box.id, finalChargeableWeightKg: box.finalChargeableWeightKg })) } : undefined;
  const suggestedAmount = latestResult?.calculatedAmount ?? selected?.recalculations?.[0]?.calculatedAmount ?? selected?.prechargedAmount;
  const confirmCancellation = (item: any, approved: boolean) => Modal.confirm({ title: approved ? '确认取消退款' : '拒绝取消退款', content: approved ? `将向客户退回 ${item.currency} ${item.refundAmount}。` : '拒绝后订单保持已取消，预扣金额不退回。', okText: approved ? '确认退款' : '确认拒绝', okButtonProps: approved ? { type: 'primary' } : { danger: true }, onOk: async () => { try { await request(`/admin/v1/billing/cancellation-refunds/${item.id}/confirm`, { method: 'POST', body: JSON.stringify({ approved }) }); message.success(approved ? '取消退款已确认并写入余额流水' : '取消退款已拒绝'); await refresh(); } catch (error) { message.error(errorText(error)); throw error; } } });
  return <section className="workspace-panel"><Typography.Title level={2}>订单对账</Typography.Title><Alert className="status-alert" type="warning" showIcon message="重算不会调整余额；会计确认才会补扣或退款" description="默认按订单创建日期匹配成本、利润、燃油与服务附加费。按箱计价必须录入每一箱最终收费重。" />
    <Card size="small" title="取消退款待办" style={{ marginBottom: 16 }}><Table size="small" rowKey="id" dataSource={data.cancellationRefunds} pagination={{ pageSize: 8 }} locale={{ emptyText: '暂无取消退款待办' }} columns={[{ title: '订单', render: (_: unknown, item: any) => item.order?.carrierTrackingNumber ?? item.order?.orderNo }, { title: '客户', render: (_: unknown, item: any) => item.order?.customer?.username }, { title: '退款金额', render: (_: unknown, item: any) => `${item.currency} ${item.refundAmount}` }, { title: '状态', dataIndex: 'status', render: (value: any) => <Tag>{value === 'PENDING_FINANCE_CONFIRMATION' ? '待会计确认' : value === 'CONFIRMED' ? '已退款' : '已拒绝'}</Tag> }, { title: '操作', render: (_: unknown, item: any) => item.status === 'PENDING_FINANCE_CONFIRMATION' ? <Space><Button size="small" type="primary" onClick={() => confirmCancellation(item, true)}>确认退款</Button><Button size="small" danger onClick={() => confirmCancellation(item, false)}>拒绝</Button></Space> : '—' }]} /></Card>
    <Table rowKey="id" dataSource={data.reconciliations} pagination={{ pageSize: 15 }} columns={[{ title: '订单', render: (_: unknown, item: any) => item.order?.carrierTrackingNumber ?? item.order?.orderNo }, { title: '客户', render: (_: unknown, item: any) => item.order?.customer?.username }, { title: '服务', render: (_: unknown, item: any) => item.order?.service?.name }, { title: '预扣金额', render: (_: unknown, item: any) => `${item.currency} ${item.prechargedAmount}` }, { title: '最近重算', render: (_: unknown, item: any) => item.recalculations?.[0] ? `${item.currency} ${item.recalculations[0].calculatedAmount}` : '—' }, { title: '最终应收', dataIndex: 'finalAmount', render: (value: any, item: any) => value == null ? '待确认' : `${item.currency} ${value}` }, { title: '状态', dataIndex: 'status', render: (value: any) => <Tag>{value}</Tag> }, { title: '操作', render: (_: unknown, item: any) => <Space><Button size="small" disabled={item.status !== 'PENDING_FINANCE_CONFIRMATION'} onClick={() => { setRecalculating(item); setLatestResult(null); }}>重算</Button><Button type="primary" size="small" disabled={item.status !== 'PENDING_FINANCE_CONFIRMATION'} onClick={() => { setSelected(item); setLatestResult(null); }}>会计确认</Button></Space> }]} />
    <Modal open={Boolean(recalculating)} destroyOnClose title="按实际收费重重算" footer={null} onCancel={() => setRecalculating(null)}><Form key={recalculating?.id} layout="vertical" initialValues={recalcInitial} onFinish={recalculate}><Form.Item name="asOfDate" label="计费日期" rules={[{ required: true }]} extra="默认订单创建日期，可改选其他计费日期"><Input type="date" /></Form.Item>{recalculating?.order?.service?.measurementMethod === 'PER_BOX' ? <><Alert type="info" showIcon message="按箱计价：必须填写每个箱号的最终收费重" /><Form.List name="boxes">{(fields) => <>{fields.map((field) => { const box = recalculating.order.boxes[field.name]; return <Row gutter={10} key={field.key}><Col span={12}><Form.Item label="箱号"><Input value={box?.boxNo} disabled /></Form.Item></Col><Col span={12}><Form.Item name={[field.name, 'finalChargeableWeightKg']} label="最终收费重 kg" rules={[{ required: true }]}><Input /></Form.Item><Form.Item name={[field.name, 'boxId']} hidden><Input /></Form.Item></Col></Row>; })}</>}</Form.List></> : <Alert type="info" showIcon message={`按票计价：使用已从供应商账单回填的整票最终收费重 ${recalculating?.order?.finalChargeableWeightKg ?? '（尚未录入）'} kg`} />}<Button type="primary" htmlType="submit" loading={busy}>执行重算</Button></Form></Modal>
    <Modal open={Boolean(selected)} destroyOnClose title="确认最终应收" footer={null} onCancel={() => { setSelected(null); setLatestResult(null); }}><Typography.Paragraph>订单：{selected?.order?.carrierTrackingNumber ?? selected?.order?.orderNo}<br />预扣金额：{selected?.currency} {selected?.prechargedAmount}<br />{latestResult && <>最近重算：{selected?.currency} {latestResult.calculatedAmount}</>}</Typography.Paragraph><Form key={`${selected?.id}-${suggestedAmount}`} layout="vertical" initialValues={{ finalReceivableAmount: suggestedAmount }} onFinish={confirm}><Form.Item name="finalReceivableAmount" label="最终应收金额" rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="confirmationNote" label="确认备注"><Input.TextArea rows={3} /></Form.Item><Button type="primary" htmlType="submit" loading={busy}>确认并调整余额</Button></Form></Modal>
  </section>;
}

function SupplierBills({ data }: Context) { return <section className="workspace-panel"><Typography.Title level={2}>供应商账单导入</Typography.Title><Table rowKey="id" dataSource={data.bills} columns={[{ title: '文件', dataIndex: 'originalFilename' }]} /></section>; }
function Reconciliation({ data }: Context) { return <section className="workspace-panel"><Typography.Title level={2}>订单对账</Typography.Title><Table rowKey="id" dataSource={data.reconciliations} columns={[]} /></section>; }
